-- PeaklyPrep: PeaklyTest Dec 2025 — full practice test from the PeaklyTest library (December 2025 form) --------
-- Generated from the PeaklyTest PDF: questions, answer choices, answer keys and explanations.
-- Figures live in public/q/dec25/. Ids are fixed, so running this file again updates the test instead of copying it.

-- PeaklyTest Dec 2025 · Reading & Writing · Module 1
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('ea626edb-e59a-51ca-b137-db023721e611', 'PeaklyTest Dec 2025 · Reading & Writing · Module 1', 'Reading & Writing', 'Reading & Writing, Module 1 of the Dec 2025 PeaklyTest · 27 questions · 32 minutes', 32, 100, true, 'PeaklyTest Dec 2025 · Reading & Writing', 1)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('4ff4ac99-aeab-5b01-995e-2165170c4f5c', 'ea626edb-e59a-51ca-b137-db023721e611', 'As used in the text, what does the word “surveyed” most nearly mean?', '["Transformed", "Organized", "Examined", "Guaranteed"]'::jsonb, 1, 'The following text is from Mark Twain’s 1876 novel The Adventures of Tom Sawyer. Tom, a child, has been told by his aunt to paint their house’s fence.

Tom appeared on the sidewalk with a bucket of whitewash and a long-handled brush. He <u>surveyed</u> the fence, and all gladness left him and a deep melancholy settled down upon his spirit. Thirty yards of board fence nine feet high.'),
  ('6fe2c9e9-4bf2-5af4-be3e-a72fcf6518a7', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text with the most logical and precise word or phrase?', '["subtle", "apparent", "unusual", "excessive"]'::jsonb, 2, 'The influence of William Shakespeare’s writings is clear in a vast range of subsequent literary works and is similarly _____ in many works in other media, from fine art (such as Edward Alcock’s painting Portia and Shylock) to popular music (such as the musician Elvis Costello’s song “Miss Macbeth”).'),
  ('8da40443-8670-564f-aec6-112087ce7414', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text with the most logical and precise word or phrase?', '["salvage", "improve", "amend", "simplify"]'::jsonb, 3, 'The Apollo Moon landings (1969–1972) brought atmospheric sensors and soil sensors to the Moon and produced large amounts of data, much of which was stored on technologies that are now obsolete. A data-transfer project is working to _____ these data so that the information is available to researcher Noah Petro, who is investigating the geology of the Moon.'),
  ('c6469413-0714-5bc4-8b19-611214524036', 'ea626edb-e59a-51ca-b137-db023721e611', 'As used in the text, what does the word “breathes” most nearly mean?', '["Rejects", "Imparts", "Absorbs", "Acquiesces"]'::jsonb, 4, 'The following text is adapted from the 1895 poem “Ojistoh” by Emily Pauline Johnson, a Kanienkahagen (Mohawk) writer also known as Tekahionwake.

I am Ojistoh, I am she, the wife
Of him whose name <u>breathes</u> bravery and life
And courage to the tribe who calls him chief.
I am Ojistoh, his white star, and he
Is land, and lake, and sky—and soul to me.'),
  ('bf5a5f5b-3bc2-593a-babd-2157dddea737', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text with the most logical and precise word or phrase?', '["restrains", "replicates", "characterizes", "transcends"]'::jsonb, 5, 'Mastering ‘ajami, a Syrian art of creating intricately painted wood panels, demands a skill set that ______ innate talent: crafting the panels requires not just the ability to draw but also an understanding of traditional techniques, materials, and design elements, necessitating expertise gained through dedicated guidance from experienced artisans.'),
  ('56cd639c-4eaf-51b9-af0f-4f03ee7dd37c', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It states the results of the experiment discussed in the text.", "It indicates the question that the study discussed in the text was meant to answer.", "It explains an important part of the design of the experiment discussed in the text.", "It illustrates a problem that inspired the study discussed in the text."]'::jsonb, 6, 'In factories, humans and robots often work together. A research team ran an experiment to find out how working with robots affects relationships between human coworkers. The experiment included teams working together to make electric motor parts. <u>One type of team included only humans and the other</u> <u>type included both humans and robots.</u> Participants were paid for their work and were asked about their willingness to share their earnings with their human teammates. Participants from teams with robots were more likely to share with each other than participants from teams with only humans were.'),
  ('46813903-446c-534d-8afc-f271c2147c09', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It illustrates the widespread influence of a play discussed earlier in the text.", "It provides additional information about a person mentioned in the text.", "It emphasizes the ongoing significance of the theater company discussed in the text.", "It explains the circumstances that led to the formation of the theater company discussed in the text."]'::jsonb, 7, 'Steve Carter’s award–winning play Eden was produced in 1976 by the groundbreaking Negro Ensemble Company (NEC). NEC cofounder Douglas Turner Ward, who worked as an actor, director, and playwright, had met actor and producer Robert Hooks while they were performing in a 1960 touring production of Lorraine Hansberry’s play A Raisin in the Sun. Together, they envisioned a theater company that would nurture and showcase the work of Black theater professionals. <u>Since NEC’s founding in 1967, its</u> <u>workshops and performances have given Black playwrights, including Carter, a forum for their compelling</u> <u>stories.</u>'),
  ('788e930e-c34f-5a6b-95f8-33800165ea8c', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice best describes the overall structure of the text?', '["It outlines recent efforts to confirm the presence of a particular gas in Venus’s atmosphere, summarizes a research team’s evaluations of those efforts’ methodological shortcomings, and then explains why that team remains skeptical of the gas’s future detection.", "It compares the levels of a particular gas on Venus and Earth, sketches the chemical processes that account for differences in these levels, and then addresses some of the practical challenges of studying the presence of this gas on Venus more closely.", "It explains why the consensus view of a particular gas in Venus’s atmosphere has recently become controversial, expands on a scientific team’s reasons for questioning that consensus, and then suggests that future observations of Venus’s atmosphere will likely be needed to settle the controversy.", "It introduces an unexpected observation of a particular gas in Venus’s atmosphere, presents an effort to investigate possible mechanisms that could explain that observation, and then notes an implication of that investigation’s findings."]'::jsonb, 8, 'Despite potential independent confirmation, the apparent detection in 2020 of phosphine (PH3)—a gas

that on Earth almost exclusively derives from biological sources—in Venus’s cloud deck remains controversial, in part because Venus is thought to be uninhabitable. To evaluate such a finding’s plausibility, William Bains et al. modeled multiple abiotic PH3 pathways, including geochemical,

atmospheric, and photochemical reactions, but none adequately explain the observed levels of PH3. If

Venusian PH3 does exist, it would indicate insufficiencies in the current consensus on Venus’s chemistry.'),
  ('1897425e-7894-5c39-aedc-8d23693dece2', 'ea626edb-e59a-51ca-b137-db023721e611', 'Based on the text, what do Stern and Gerya most likely believe about the development of complex life on exoplanets?', '["It is more likely to occur on habitable zone planets with atmospheres and plate tectonics than on otherwise similar planets that lack plate tectonics.", "It is more likely to occur if habitable zone planets with atmospheres transition from single-lid to plate tectonics late in their history than if they transition early in their history.", "It is probably more dependent on the presence of plate tectonics than on orbital distance from a host star or the presence of an atmosphere.", "It is unlikely unless the transition from single-lid to plate tectonics occurs before the acquisition of a lasting atmosphere."]'::jsonb, 9, 'Given the immense scope of space, the search for extraterrestrial life is almost necessarily concentrated on the exoplanets deemed to have the most plausible chance of success—typically, atmosphere-bearing terrestrial planets orbiting within a certain range of their stars (termed the habitable zone). Claiming that Earth experienced a long transition from single-lid to plate tectonics that accelerated the emergence and evolution of complex organisms, researchers Robert J. Stern and Taras V. Gerya hold that consideration of tectonics, an often overlooked factor, could help further narrow the search for advanced extraterrestrial species.'),
  ('a8cfb017-5532-5f8d-af2d-39fee8fe1277', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice best states the main idea of the text?', '["When staging Indigenous exhibits, non-Indigenous institutions should follow the example of the cultural centers operated by the Tulalip Tribes and the Turtle Mountain Band of Chippewa.", "The cultural centers operated by the Tulalip Tribes and the Turtle Mountain Band of Chippewa differ in strategy from non-Indigenous museums that stage Indigenous exhibits.", "Whereas non-Indigenous institutions stage exhibits on a wide array of subjects, the cultural centers operated by the Tulalip Tribes and the Turtle Mountain Band of Chippewa serve primarily to present Indigenous history and cultures.", "The strategy used by the Tulalip Tribes to present history and culture to tribal citizens differs only slightly from the strategy used in the Turtle Mountain Band of Chippewa"]'::jsonb, 10, 'In what is now Washington state, the Tulalip Tribes operate the Hibulb Cultural Center. Relying on traditional knowledge to guide the design of exhibits, this institution presents Tulalip history and culture to the tribes’ citizens. The Turtle Mountain Band of Chippewa, a tribe in North Dakota, employs a similar strategy in its own cultural center. Both centers contrast with museums that aren’t Indigenous-led; when displaying Indigenous artifacts, such museums tend to anticipate mainly non-Indigenous audiences and rely on Euro-centric strategies for designing exhibits.'),
  ('4ca2bf61-e4cc-5eaa-ae6f-2f1bf118c3f3', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which quotation from The Wonderful Wizard of Oz most effectively illustrates the claim?', '["a character says to Dorothy, \"I cannot understand why you should wish to leave this beautiful country and go back to the dry, gray place you call Kansas.\"", "a character says to others, \"But it will take more than imagination to carry Dorothy back to Kansas, and I’m sure I don’t know how it can be done.\"", "the narrator states, \"Dorothy did not feel nearly so bad as you might think a little girl would who had been suddenly whisked away from her own country and set down in the midst of a strange land.\"", "the narrator states, \"Before them was a great stretch of country having a floor as smooth and shining and white as the bottom of a tin.\""]'::jsonb, 11, 'The Wonderful Wizard of Oz is a 1900 novel by L. Frank Baum. In the novel, Dorothy, who is from Kansas, finds herself in an unfamiliar place called Oz. Kansas is presented as being less appealing than Oz, as is clear when _____'),
  ('d813e424-7bd7-5f7a-b68f-058177e459bb', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice most effectively uses data from the table to complete the student’s conclusion?', '["the percent decrease in hours worked was greater in Portugal than it was in France, Argentina, or Israel.", "while the number of hours worked rose in Portugal between 1950 and 2017, it declined in France, Argentina, and Israel.", "though the decline in number of hours worked in Portugal was less than that in France and Israel, it was greater than that in Argentina.", "though the decline in number of hours worked in Portugal was not as great as that in France, it was greater than that in Argentina and Israel."]'::jsonb, 12, '**Average Hours Worked per Person per Year in 1950 and 2017**

| Country | 1950 | 2017 | Change in hours | Percent change in hours |
| Argentina | 2,034 | 1,692 | −342 | −17% |
| Portugal | 2,399 | 1,863 | −536 | −22% |
| Israel | 1,966 | 1,921 | −45 | −2% |
| France | 2,193 | 1,514 | −679 | −31% |

Calculations may be inexact due to rounding.

A student in an economics course is examining the decline since 1950 in average hours worked per person per year in various nations due to both increased productivity and the adoption of policies that limit working hours. The student researches how the decline in Portugal compares to that in other countries.'),
  ('e113d339-9033-5d19-b3d9-fb236296a223', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which quotation from Cane most effectively illustrates the claim?', '["“And when the wind is from the South, soil of my homeland falls like a fertile shower upon the lean streets of [Washington, DC].”", "“The Dixie Pike has grown from a goat path in Africa.”", "“From down the railroad track, the chug–chug of a gas engine announces that the repair gang is coming home.”", "“One evening I walked up the [Dixie] Pike on purpose, and stopped to say hello [to Fern].”"]'::jsonb, 13, 'Cane is a 1923 novel by Jean Toomer. In the novel, Toomer mentions a road in rural Georgia called Dixie Pike and describes it as having a deep connection to a faraway place, writing, ______'),
  ('d76fbcca-85e2-53a9-b763-72e39bc3bb3a', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which quotation from the costume designer for the modern production of Our Town would most effectively support the student’s claim?', '["“Although historically accurate costumes would have added an air of authenticity to Our Town, they have so many layers that costume changes would have been difficult.”", "“The clothing of the period of Our Town is aesthetically appealing but largely unfamiliar to today’s audiences, so minor deviations from historical accuracy largely went unnoticed.”", "“For Our Town, I decided not to include the extra fabric that would have been typical of clothing in the period because it made the costumes unappealingly bulky.”", "“In trying to create the period look of Our Town, I had to make some practical compromises, such as substituting cooler modern fabrics for historically accurate woolens so that the actors didn’t overheat.”"]'::jsonb, 14, 'The 1980 production of Charlie and Algernon was the first Broadway show for which Jess Goldstein was credited as a costume designer. Goldstein was among the Broadway costume designers interviewed by Sara Jablon-Roberts and Eulanda A. Sanders for their study of historical accuracy in costume design. They argue that aesthetics often outweigh fidelity to the past among designers for shows with historical settings. In a paper for a theater class, a student claims that the costume design for a modern production of the musical Our Town (set in the early 1900s) exemplifies this tendency.'),
  ('3b12d2d1-eb6f-5b80-a81d-efb0f5b9677f', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice most logically completes the text?', '["the humans who were alive at the same time as the fox most likely ate more meat than the fox did.", "the humans who were alive at the same time as the fox hunted using the spears whose points were also found at the site.", "the fox may have been a companion animal of the humans who inhabited the site at the same time.", "the fox had a diet more similar to that of jackals than to that of wild foxes."]'::jsonb, 15, 'Zooarchaeologist Ophélie Lebrasseur and her team examined a fox skeleton discovered in 1991 at an archaeological site alongside artifacts of human habitation (like spear points) in central Argentina. Lebrasseur et al. determined that the fox was Dusicyon avus, an extinct species resembling a jackal, and radiocarbon dating placed the fox at the site at the same time as human inhabitants. (Indeed, the inhabitants may have deliberately buried the fox.) In addition, while wild foxes have a diet entirely made of meat, isotopic signatures of the skeleton’s teeth indicated that the fox’s diet, like that of the humans, was partly composed of plant material. Lebrasseur et al. therefore concluded that ______'),
  ('c563e1eb-28ae-5c65-9703-cc0bf64d4bd4', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["having campaigned", "campaigned", "campaigning", "to campaign"]'::jsonb, 16, 'In the nineteenth century, Elizabeth Cady Stanton and Susan B. Anthony _____ for women’s right to vote in the United States.'),
  ('91c6e9a8-6040-53ce-9855-5bc05c0e17dc', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["her favorite book was.", "was her favorite book?", "her favorite book was?", "was her favorite book!"]'::jsonb, 17, 'While conducting an interview for her book Latina Authors and Their Muses, editor Mayra Calvani asked Sarah Cortez, author of the memoir Walking Home, what _____ Cortez’s response was Bury Me Deep by Megan Abbott.'),
  ('668d069c-c585-52a5-adf1-708e0d13e7c0', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["dance, it showcased", "dance. Which showcased", "dance, showcasing", "dance. Showcasing"]'::jsonb, 18, 'Choreographers George Balanchine and Martha Graham both contributed sections to the dance piece Episodes, which premiered at New York’s City Center of Music and Drama in 1959. This cross-genre collaboration brought together the distinct features of Balanchine’s neoclassical ballet and Graham’s modern ______ the stylistic diversity and creative innovation within the dance world.'),
  ('3229f1ee-435c-52cd-a6df-e2363c9176d4', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["improvising which", "improvising and which", "improvising. Which", "improvising, which"]'::jsonb, 19, 'In the book A Theory of Harmony (1985), Swiss musicologist Ernst Levy argued that every chord has an opposite that can be substituted for it. For example, a pianist could replace the vi chord for the bIII chord while _____ chord is a given chord’s opposite can be determined using a music visualization tool called the circle of fifths.'),
  ('f1348988-7e1a-539c-b578-7d4fc1f6f45b', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Mendieta was hoping", "Mendieta hoped", "Mendieta had hoped", "Mendieta, hoping"]'::jsonb, 20, 'In her Silueta sculpture series, the Cuban American artist Ana _____ to access what she called an “omnipresent female force,” utilized a variety of natural materials to create outlines—or silhouettes—of her own body.'),
  ('56c70c12-df2c-55dc-9918-d46a32b13b4b', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text with the most logical transition?', '["in any case,", "in contrast,", "in conclusion,", "in fact,"]'::jsonb, 21, 'As volcanologists like Tamsin Mather are apt to make clear, not all volcanoes are the same. Tendürek in Turkey, for example, is a shield volcano, a type of volcano named for its low profile, resembling a warrior’s shield lying on the ground. Opala in Russia, _____ is a caldera, a large cauldron-like hollow that forms shortly after the emptying of a magma chamber in a volcanic eruption.'),
  ('b626a4aa-7cbe-5ab6-a703-75881f9b351b', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text with the most logical transition?', '["In a broader sense,", "Within this category,", "In the future,", "Despite this majority,"]'::jsonb, 22, 'The United Nations’ Trade and Development organization divides exports into five key categories: food items, agricultural materials, fuels, ores and raw metals, and manufactured goods (i.e., most nonfood goods made by machinery or by hand). In 2022, the majority (62 percent) of Belgium’s exports were manufactured goods. _____ vaccines, medicines, and cars were its top exports.'),
  ('be933a50-b7cf-5f46-b363-5157aab88b1a', 'ea626edb-e59a-51ca-b137-db023721e611', 'Which choice completes the text with the most logical transition?', '["Specifically,", "As a result,", "By contrast,", "Nevertheless,"]'::jsonb, 23, 'A research team led by Gal Badhii has discovered that chimpanzees communicate through exchanges of gestures occurring at a pace similar to that of human conversations. _____ chimpanzee gesture exchanges have short pauses of about 120 milliseconds between communications, comparable to the 200–millisecond average pause between turns in human speech.'),
  ('12280930-0dd1-5453-8bdf-3e7755916b8d', 'ea626edb-e59a-51ca-b137-db023721e611', 'The student wants to emphasize a difference between Artemia franciscana and Nodularia. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Artemia franciscana are crustaceans that live in the southern portion of the Great Salt Lake.", "Artemia franciscana and Nodularia both live in the Great Salt Lake’s southern portion.", "The northern portion of the Great Salt Lake has a higher concentration of salt than does the southern portion.", "Artemia franciscana and Nodularia are different types of organisms: Artemia franciscana are crustaceans, whereas Nodularia are bacteria."]'::jsonb, 24, 'While researching a topic, a student has taken the following notes:

The Great Salt Lake in Utah is one of the world’s saltiest bodies of water.
The northern portion of the lake has a higher concentration of salt than the southern portion. Crustaceans called Artemia franciscana live in the southern portion.
Bacteria called Nodularia live in the southern portion.'),
  ('4560eb68-b3e3-5de5-8299-22443847b9d6', 'ea626edb-e59a-51ca-b137-db023721e611', 'The student wants to emphasize a similarity between the astronauts Mastracchio and Reisman. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Reisman has spent less time performing spacewalks than Mastracchio has.", "EVAs, also known as spacewalks, are activities done by astronauts outside a spacecraft.", "Mastracchio and Reisman have each performed multiple spacewalks.", "Mastracchio has performed spacewalks, but Reisman has performed EVAs."]'::jsonb, 25, 'While researching a topic, a student has taken the following notes:

Extravehicular activities (EVAs) are activities performed outside a spacecraft by astronauts in outer space.
EVAs are also known as spacewalks.
Richard Mastracchio is a former US astronaut who has performed 9 spacewalks.
The total time of Mastracchio’s spacewalks was 53 hours and 4 minutes.
Garrett Reisman is a former US astronaut who has performed 3 spacewalks.
The total time of Reisman’s spacewalks was 21 hours and 21 minutes.'),
  ('6e919401-82a4-554c-bbb3-11f6f45a87df', 'ea626edb-e59a-51ca-b137-db023721e611', 'The student wants to emphasize the role the US Fish & Wildlife Service plays in safeguarding the habitat of the light-footed clapper rail. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["By limiting human activities in the Tijuana Slough NWR, the US Fish & Wildlife Service safeguards the habitat of the light-footed clapper rail.", "Human activities are limited in the Tijuana Slough NWR, a protected natural area in California.", "Home to the light-footed clapper rail, the Tijuana Slough NWR is located in California, where it encompasses 1,023 acres.", "The 1,023-acre Tijuana Slough NWR was established to safeguard the habitat of the light-footed clapper rail, an endangered species."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

The Tijuana Slough National Wildlife Refuge (NWR) is a protected natural area in California. It encompasses 1,023 acres.
The Tijuana Slough NWR was established to safeguard the habitat of the light-footed clapper rail, an endangered species.
The Tijuana Slough NWR is managed by the US Fish & Wildlife Service.
The US Fish & Wildlife Service limits human activities in the area.'),
  ('97d39abb-a378-5532-ba8a-54334ee9f2ad', 'ea626edb-e59a-51ca-b137-db023721e611', 'The student wants to identify a language that was written using the cuneiform script. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["Examples of Mesopotamian writing that are nearly 5,000 years old have been found.", "A language in ancient Mesopotamia used the cuneiform script for writing.", "Clay tablets with cuneiform script have been found in present-day Iraq.", "Sumerian, an ancient Mesopotamian language, was written using the cuneiform script."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

The cuneiform script is the earliest known set of symbols used for writing.
Sumerian was one of the first languages to be written using the cuneiform script.
Sumerian was a language in ancient Mesopotamia (present-day Iraq).
Clay tablets with Sumerian writing have been found there.
Some of these tablets are almost 5,000 years old.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('4ff4ac99-aeab-5b01-995e-2165170c4f5c', 2, null, '**Choice C is correct.** In the context, Tom "appeared on the sidewalk with a bucket of whitewash and a long-handled brush. He surveyed the fence, and all gladness left him..." The sentence describes his immediate reaction to seeing the task and the fence’s size, so "surveyed" means he looked over or examined the fence.
**Choice A is incorrect.** "Transformed" means changed into something else; nothing in the context suggests Tom changed the fence before starting.
**Choice B is incorrect.** "Organized" implies arranging or ordering; the passage describes Tom’s observation, not any rearrangement.
**Choice D is incorrect.** "Guaranteed" means assured or promised; the sentence conveys Tom’s inspection and emotional response, not a promise.
**Faster approach:** Use immediate context — the phrase about his reaction and the fence’s dimensions indicates physical observation, so pick the synonym "examined" without overthinking.'),
  ('6fe2c9e9-4bf2-5af4-be3e-a72fcf6518a7', 1, null, '**Choice B is correct.** The sentence says Shakespeare’s influence is “clear in a vast range of subsequent literary works” and then asserts it is “similarly _____ in many works in other media.” The parallel structure requires a word that also means noticeable or obvious; “apparent” precisely matches that meaning and preserves the intended parallelism.
**Choice A is incorrect.** “Subtle” means not obvious, which contradicts the statement that the influence is “clear” in literary works and would break the parallel meaning.
**Choice C is incorrect.** “Unusual” changes the meaning to something being uncommon rather than noticeable, which does not follow from the first clause.
**Choice D is incorrect.** “Excessive” implies too much or overly abundant, which is not implied by saying the influence is clear; it changes the sense of the sentence.
**Faster approach:** Match the meaning of “clear” in the first clause to maintain parallelism; eliminate antonyms and meaning-shifts, leaving “apparent.”'),
  ('8da40443-8670-564f-aec6-112087ce7414', 0, null, '**Choice A is correct.** The context says the data were stored on technologies that are now obsolete, and a data-transfer project aims to make the information available to a researcher. "Salvage" precisely conveys recovering or rescuing data from outdated media so they can be used. It fits the tone and purpose of the sentence without implying unnecessary changes to the data.
**Choice B is incorrect.** "Improve" would mean making the data better, but the sentence focuses on making obsolete-stored data accessible, not enhancing their quality.
**Choice C is incorrect.** "Amend" means to change or correct, which is not implied; the goal is access to existing data, not alteration.
**Choice D is incorrect.** "Simplify" suggests reducing complexity; that does not address the problem of outdated storage preventing access.
**Faster approach:** Look for a word that matches the problem introduced (data trapped on obsolete media) and the goal (make it available): a recovery synonym like "salvage" is the best fit.'),
  ('c6469413-0714-5bc4-8b19-611214524036', 1, null, '**Choice B is correct.** In the line “Of him whose name breathes bravery and life,” the verb “breathes” is used metaphorically to indicate that the chief’s name gives or conveys qualities (bravery and life) to others. The common idiom “to breathe life into” means to impart or give vitality, so “imparts” best matches that sense.
**Choice A is incorrect.** “Rejects” means to refuse or dismiss, which contradicts the positive sense of giving bravery and life.
**Choice C is incorrect.** “Absorbs” means to take in, but the context implies the name projects qualities outward, not takes them in.
**Choice D is incorrect.** “Acquiesces” means to accept or comply reluctantly, which doesn’t fit the active, generative sense of “breathes” here.
**Faster approach:** Replace the figurative verb with a familiar idiom (e.g., “breathes life into”) to see that it means “gives” or “imparts,” then choose the answer with that meaning.'),
  ('bf5a5f5b-3bc2-593a-babd-2157dddea737', 3, null, '**Choice D is correct.** The sentence contrasts simple drawing ability with a broader set of learned skills; the phrase "requires not just... but also" signals that the skill set goes beyond innate talent. "Transcends" precisely expresses "goes beyond" or "exceeds" innate talent, matching the intended contrast.
**Choice A is incorrect.** "Restrains" means to limit or hold back, which conflicts with the sentence’s meaning that additional learned skills are required rather than limited by innate talent.
**Choice B is incorrect.** "Replicates" means to copy or reproduce; the sentence does not say the skill set copies innate talent, so this choice is not supported by context.
**Choice C is incorrect.** "Characterizes" means to be a defining feature of something; the passage indicates the skill set goes beyond innate talent rather than simply defining it, so this option is not precise.
**Faster approach:** Look for the signal phrase "not just... but also" to identify a contrast; choose the answer meaning "goes beyond" (i.e., "transcends").'),
  ('56cd639c-4eaf-51b9-af0f-4f03ee7dd37c', 2, null, '**Choice C is correct.** The underlined sentence specifies how the experiment was set up by describing the two kinds of teams used: teams of only humans and teams of humans plus robots. This is a description of an important element of the experimental design that allows comparison of outcomes between those two conditions.
**Choice A is incorrect.** The results are stated later in the passage (that participants from teams with robots were more likely to share), so the underlined sentence does not state the experiment’s outcome.
**Choice B is incorrect.** The question the study addressed is described in the first sentence (how working with robots affects relationships), not by the underlined sentence.
**Choice D is incorrect.** The underlined sentence does not present a motivating problem; it describes the experimental setup rather than an inspiration for the study.
**Faster approach:** For questions about a sentence’s function, ask whether it defines the study, states results, poses the research question, or gives background; match the sentence to those categories to eliminate wrong answers quickly.'),
  ('46813903-446c-534d-8afc-f271c2147c09', 2, null, '**Choice C is correct.** The underlined sentence shifts from the historical founding details to a statement about NEC’s continuing role: it says that "since" 1967 the company’s workshops and performances "have given" Black playwrights a forum. That wording highlights NEC’s ongoing significance and impact over time, which functions to underscore the company’s lasting importance in nurturing writers like Carter.
**Choice A is incorrect.** The sentence does not describe the influence of a specific play; it describes the activities and role of the theater company rather than the reach of a particular production.
**Choice B is incorrect.** The sentence concerns the theater company (NEC) and its role in supporting playwrights, not providing additional information about a person mentioned earlier.
**Choice D is incorrect.** The circumstances that led to NEC’s formation are given in the previous sentences (the meeting of Ward and Hooks and their vision); the underlined sentence instead describes what NEC has done since its founding, not how it was formed.
**Faster approach:** Look for signal words (like "since") and verb tense (present perfect "have given") to decide whether a sentence describes ongoing/significant effect (choice C) versus formation/explanation (choice D) or detail about a person (B).'),
  ('788e930e-c34f-5a6b-95f8-33800165ea8c', 3, null, '**Choice D is correct.** The passage first notes an unexpected 2020 detection of phosphine in Venus’s clouds, then describes William Bains et al.’s modeling of abiotic PH$3$ pathways to explain that observation, and finally states the implication that, if the phosphine is real, current chemical consensus about Venus is inadequate. This sequence matches D’s observation → investigation → implication structure.
**Choice A is incorrect.** The passage does not outline efforts to "confirm" the gas nor summarize methodological shortcomings of detection; it focuses on modeling possible abiotic sources and the implication for Venusian chemistry, not on detection methods or skepticism about future detection.
**Choice B is incorrect.** The passage does not compare gas levels on Earth and Venus or sketch processes that account for those level differences; it only notes that on Earth PH$3$ is mostly biological and then considers abiotic pathways for Venus.
**Choice C is incorrect.** Although the passage mentions controversy, it does not argue that future observations "will likely be needed" to settle the issue; instead it reports modeling results and their implication for chemical consensus, not a call for future observation.
**Faster approach:** For text-structure questions, identify the passage’s sequence of ideas (e.g., observation → analysis → implication). Match that sequence to the answer choices to eliminate options whose order or content doesn’t align.'),
  ('1897425e-7894-5c39-aedc-8d23693dece2', 0, null, '**Choice A is correct.** The passage explains that searches usually focus on atmosphere-bearing terrestrial planets in the habitable zone and that Stern and Gerya argue Earth’s long transition to plate tectonics "accelerated the emergence and evolution of complex organisms." They say that considering tectonics could further narrow the search for advanced species, which implies that planets with atmospheres and plate tectonics are more likely sites for complex life than otherwise similar planets lacking plate tectonics.
**Choice B is incorrect.** The passage notes a "long transition" on Earth but does not compare early versus late transitions or claim timing increases likelihood.
**Choice C is incorrect.** The authors suggest tectonics is an important, previously overlooked factor to add to existing criteria (habitable zone and atmosphere), not that it outweighs those other factors.
**Choice D is incorrect.** The passage gives no basis for a requirement that tectonic transition precede atmosphere acquisition.
**Faster approach:** Use elimination: match the authors’ explicit claims (tectonics helps explain Earth’s complex life and should be added to habitable-zone/atmosphere criteria) to eliminate choices that introduce unsupported comparisons about timing or priority.'),
  ('a8cfb017-5532-5f8d-af2d-39fee8fe1277', 1, null, '**Choice B is correct.** The passage describes how the Tulalip and Turtle Mountain cultural centers use Indigenous, tradition-based strategies to present tribal history and culture and then contrasts those practices with non‑Indigenous museums that anticipate mainly non‑Indigenous audiences and use Euro‑centric exhibit design. That explicit contrast supports the statement that the tribal centers “differ in strategy” from non‑Indigenous museums.
**Choice A is incorrect.** The passage reports what the tribal centers do and contrasts them with other museums; it does not argue that non‑Indigenous institutions should follow their example.
**Choice C is incorrect.** Although the centers do present Indigenous history and culture, this choice omits the central contrast with non‑Indigenous museums emphasized in the passage.
**Choice D is incorrect.** The passage says the two tribal centers employ a similar strategy, not that their strategies differ only slightly; moreover, the main point is the contrast with non‑Indigenous museums.
**Faster approach:** Look for contrast words (e.g., "both," "contrast," "when") to identify whether the main idea is a comparison; choose the answer that restates that comparison.'),
  ('4ca2bf61-e4cc-5eaa-ae6f-2f1bf118c3f3', 0, null, '**Choice A is correct.** The quotation directly contrasts Oz and Kansas by calling Oz a "beautiful country" and describing Kansas as a "dry, gray place," which most clearly and explicitly supports the claim that Kansas is presented as less appealing than Oz.
**Choice B is incorrect.** This line concerns the logistics of returning Dorothy to Kansas and says nothing about the relative appeal or description of either place.
**Choice C is incorrect.** That narrator comment describes Dorothy’s emotional reaction (she did not feel as bad as expected) but does not explicitly compare the attractiveness of Kansas and Oz.
**Choice D is incorrect.** The narrator’s description of Oz’s landscape is vivid but does not by itself contrast Oz with Kansas or state that Kansas is less appealing.
**Faster approach:** For questions asking which quotation supports a comparative claim, scan choices for language that explicitly compares the two items (words like "more," "less," or direct contrasting adjectives); select the choice that directly states the contrast.'),
  ('d813e424-7bd7-5f7a-b68f-058177e459bb', 3, null, '**Choice D is correct.** The table shows Portugal’s change as −536 hours, France’s as −679 hours, Argentina’s as −342 hours, and Israel’s as −45 hours. Because −536 is a smaller (less negative) decline than −679, Portugal’s decline was not as great as France’s; because −536 is a larger decline than −342 and −45, Portugal’s decline was greater than Argentina’s and Israel’s.
**Choice A is incorrect.** Portugal’s percent decrease (−22%) is smaller than France’s (−31%), so it is not greater than all three.
**Choice B is incorrect.** The table shows hours in Portugal fell from 2,399 to 1,863 (a decline), so hours did not rise.
**Choice C is incorrect.** Portugal’s decline (−536) is not less than Israel’s (−45); it is much greater, so the comparison to Israel is wrong.
**Faster approach:** Look at the "Change in hours" column and directly compare the signed numbers (or their absolute magnitudes) to determine which declines are larger or smaller.'),
  ('e113d339-9033-5d19-b3d9-fb236296a223', 1, null, '**Choice B is correct.** The claim says the Dixie Pike is described as having a deep connection to a faraway place; Choice B explicitly makes that connection by asserting, “The Dixie Pike has grown from a goat path in Africa,” directly linking the road’s origin to a distant, nonlocal place and so most effectively illustrates the claim.
**Choice A is incorrect.** Although it evokes a homeland and distant soil, it references Washington, D.C., and wind-born soil rather than directly tying the Dixie Pike itself to a specific faraway origin.
**Choice C is incorrect.** This sentence describes a local sound (a repair gang coming home) and does not establish a connection between the Pike and a distant place.
**Choice D is incorrect.** This is a mundane, local action (walking and greeting someone) and does not suggest any faraway origin or deep distant connection.
**Faster approach:** Pick the quotation that explicitly names or asserts an origin or link to a distant location—any answer that directly references a faraway place is the best match.'),
  ('d76fbcca-85e2-53a9-b763-72e39bc3bb3a', 2, null, '**Choice C is correct.** The student’s claim is that designers let aesthetic concerns outweigh historical fidelity; in C the designer explicitly says a historically accurate feature (extra fabric) was left out because it made the costumes “unappealingly bulky,” showing a deliberate choice for appearance over strict period accuracy.
**Choice A is incorrect.** A cites practical difficulty with many layers (costume changes), which supports a logistical, not aesthetic, reason for departing from accuracy.
**Choice B is incorrect.** B notes that period clothing is “aesthetically appealing” but emphasizes audience unfamiliarity and that deviations “went unnoticed,” which attributes the change to audience perception rather than the designer preferring aesthetics over accuracy.
**Choice D is incorrect.** D describes practical compromises for actor comfort (substituting fabrics), again a functional reason, not a prioritization of aesthetics over fidelity.
**Faster approach:** Scan each quotation for explicit language about choosing appearance (words like "unappealing," "aesthetic," or "style") versus practical/logistical reasons; pick the one that names aesthetics as the reason for inaccuracy.'),
  ('3b12d2d1-eb6f-5b80-a81d-efb0f5b9677f', 2, null, '**Choice C is correct.** The passage notes that the fox and humans lived at the site at the same time, that the fox may have been deliberately buried with human artifacts, and that the fox’s diet resembled the humans’ (it included plant material). Those details together reasonably support the conclusion that the fox may have been a companion animal of the humans.
**Choice A is incorrect.** Nothing in the passage provides a direct comparison of how much meat humans versus the fox ate; the passage only reports that both consumed some plant material.
**Choice B is incorrect.** Although spear points were found, the passage does not state who used them or that the humans hunted with those specific spears.
**Choice D is incorrect.** The passage contrasts the fox with wild foxes and describes it as resembling a jackal, but it does not state jackals’ diets, so this claim is unsupported.
**Faster approach:** For inference questions, eliminate answer choices that introduce details not stated in the passage and select the option directly supported by the given facts (here: contemporaneity, burial, and diet similarity).'),
  ('c563e1eb-28ae-5c65-9703-cc0bf64d4bd4', 1, null, '**Choice B is correct.** The sentence describes a completed action in the nineteenth century, so the simple past tense "campaigned" is the appropriate form. It directly and clearly states what Stanton and Anthony did: they campaigned for women’s suffrage.
**Choice A is incorrect.** "having campaigned" is a perfect participle that would need to connect to another verb (for example, "Having campaigned, they..."), but here the sentence lacks that second clause and requires a simple predicate.
**Choice C is incorrect.** "campaigning" is a present participle or gerund; it cannot serve as the main verb of this independent clause without an auxiliary (for example, "were campaigning").
**Choice D is incorrect.** "to campaign" is an infinitive form and would not correctly complete a past-time declarative sentence about what they did in the nineteenth century.
**Faster approach:** For sentences stating what someone did in a past time frame (here, "In the nineteenth century"), pick the simple past tense verb form.'),
  ('91c6e9a8-6040-53ce-9855-5bc05c0e17dc', 0, null, '**Choice A is correct.** The sentence contains an indirect question (the editor asked what the author’s favorite book was), so it should use a declarative word order and ending punctuation. "what her favorite book was." correctly completes the sentence without turning it into a direct quotation; the clause functions as the object of "asked."
**Choice B is incorrect.** "was her favorite book?" uses the word order and a question mark of a direct question; that is not appropriate here because the sentence reports the question rather than quoting it directly.
**Choice C is incorrect.** Although it uses the indirect-word order "her favorite book was," the added question mark is wrong for a reported (indirect) question.
**Choice D is incorrect.** The exclamation mark and inverted word order make this an illogical and ungrammatical completion for a reported question.
**Faster approach:** Recognize whether the sentence is reporting a question (indirect) or giving a direct quote; indirect questions use statement word order and a period, so pick the declarative option.'),
  ('668d069c-c585-52a5-adf1-708e0d13e7c0', 2, null, '**Choice C is correct.** The sentence needs a construction that links the two clauses without creating a fragment or comma splice. "dance, showcasing the stylistic diversity and creative innovation within the dance world" uses a present participial phrase that correctly and smoothly modifies the whole preceding clause, so the sentence is grammatically complete and stylistically clear.
**Choice A is incorrect.** "dance, it showcased" creates a comma splice: a comma cannot join two independent clauses without a coordinating conjunction.
**Choice B is incorrect.** "dance. Which showcased" produces a sentence fragment because "Which showcased..." cannot stand alone as an independent sentence.
**Choice D is incorrect.** "dance. Showcasing" also yields a sentence fragment; beginning a new sentence with the participial phrase leaves it without a main clause.
**Faster approach:** Prefer a participial phrase (", -ing") when you need to attach a descriptive action to the preceding clause without starting a new sentence or creating a comma splice.'),
  ('3229f1ee-435c-52cd-a6df-e2363c9176d4', 2, null, '**Choice C is correct.** Ending the first clause with a period creates two independent clauses: "a pianist could replace the vi chord for the bIII chord while improvising." The next sentence, "Which chord is a given chord’s opposite can be determined using a music visualization tool called the circle of fifths," is a grammatical subject clause headed by "Which" and correctly takes the verb "can be determined." This punctuation yields two clear, grammatical sentences.
**Choice A is incorrect.** "improvising which" produces a fused structure in which the clause that follows does not properly attach to the main clause, creating an ungrammatical run-on.
**Choice B is incorrect.** "improvising and which" creates a coordination error: "and which" cannot conjoin smoothly to form a grammatical compound predicate here.
**Choice D is incorrect.** "improvising, which" produces a dangling or ill-formed nonrestrictive clause because the clause beginning with "which" cannot modify a clear noun in the main clause, yielding an ungrammatical sentence.
**Faster approach:** If one option creates two clear, standalone sentences (period + capitalized "Which") while the others produce run-ons or dangling clauses, choose the option that ends the first sentence (period) — it usually fixes punctuation issues in questions about clause boundaries.'),
  ('f1348988-7e1a-539c-b578-7d4fc1f6f45b', 3, null, '**Choice D is correct.** The sentence needs a nonfinite participial phrase to modify the noun phrase "the Cuban American artist Ana Mendieta" and a main finite verb later in the clause. "Mendieta, hoping to access what she called an ‘omnipresent female force,’ utilized a variety of natural materials..." supplies the participial phrase "hoping to access..." that correctly modifies Mendieta and leaves "utilized" as the main verb of the clause.
**Choice A is incorrect.** "Mendieta was hoping" is a finite verb phrase; placing it before the comma would leave the clause with two finite verbs ("was hoping" and "utilized") and create an ungrammatical coordination.
**Choice B is incorrect.** "Mendieta hoped" is also a finite verb and would produce the same problem of two finite verbs without an appropriate conjunction.
**Choice C is incorrect.** "Mendieta had hoped" uses past perfect but still yields two finite verbs and fails to provide the needed participial modifier.
**Faster approach:** Identify the main verb later in the sentence ("utilized") and choose a nonfinite/participial form ("hoping") that can modify the subject without creating a second finite verb.'),
  ('56c70c12-df2c-55dc-9918-d46a32b13b4b', 1, null, '**Choice B is correct.** The sentence sets up a contrast between two different types of volcanoes: Tendürek is described as a shield volcano with a low profile, while Opala is a caldera, a very different form. The transition "in contrast," explicitly signals that the second example differs from the first, which matches the passage’s purpose of showing that "not all volcanoes are the same."
**Choice A is incorrect.** "In any case" suggests a move to a point that is true regardless of what came before, not a comparison between two different kinds; it does not signal the intended contrast.
**Choice C is incorrect.** "In conclusion" would suggest summarizing or ending the discussion, but the sentence is providing a second example rather than drawing a final conclusion.
**Choice D is incorrect.** "In fact" would be used to emphasize or reinforce a prior statement; it does not clearly mark the difference between the two types of volcanoes as effectively as "in contrast."
**Faster approach:** For transition questions, identify the logical relationship (contrast, addition, cause, conclusion) between clauses, then pick the transition that names that relationship; eliminate options that signal other relationships.'),
  ('b626a4aa-7cbe-5ab6-a703-75881f9b351b', 1, null, '**Choice B is correct.** The second sentence specifies which exports within the previously mentioned category were most important, so a transition indicating narrowing to that category is required. "Within this category," signals that the examples that follow (vaccines, medicines, and cars) are members of the manufactured-goods category, making the sentence coherent with the prior statement that 62 percent were manufactured goods.
**Choice A is incorrect.** "In a broader sense," would expand meaning rather than narrow to specific examples, so it does not logically introduce a list of particular manufactured exports.
**Choice C is incorrect.** "In the future," indicates time and would wrongly shift tense and meaning; the sentence describes 2022 data.
**Choice D is incorrect.** "Despite this majority," creates a contrast, implying the examples contradict the prior fact, which they do not.
**Faster approach:** Identify whether the next sentence gives examples (look for nouns) or contrasts/changes time; then pick the transition that signals specification ("within this category"), contrast, or time accordingly.'),
  ('be933a50-b7cf-5f46-b363-5157aab88b1a', 0, null, '**Choice A is correct.** The sentence that follows gives a specific piece of evidence that supports the preceding general claim about the pace of chimpanzee gesture exchanges, so a transition that signals a specific example or elaboration is appropriate. "Specifically," clearly introduces the detailed measurement (120 milliseconds) that illustrates the initial point about similarity to human conversational timing.
**Choice B is incorrect.** "As a result," indicates a consequence, but the following clause provides evidence, not a consequence of the discovery.
**Choice C is incorrect.** "By contrast," would signal a difference or opposition, but the detail that follows reinforces, not contradicts, the previous statement.
**Choice D is incorrect.** "Nevertheless," implies a concession or contrast, which does not match the supportive, clarifying nature of the evidence given.
**Faster approach:** Look for whether the next sentence elaborates/supports (use "Specifically") or contrasts (use "By contrast"/"Nevertheless"); pick the signal that matches the relationship.'),
  ('12280930-0dd1-5453-8bdf-3e7755916b8d', 3, null, '**Choice D is correct.** The notes identify Artemia franciscana as crustaceans and Nodularia as bacteria and therefore D clearly states the relevant difference between the two organisms.
**Choice A is incorrect.** Although factually accurate, A only restates that Artemia franciscana live in the southern portion and does not emphasize a difference between the two organisms.
**Choice B is incorrect.** B highlights a similarity (both live in the southern portion) rather than emphasizing a difference, so it fails to meet the student’s goal.
**Choice C is incorrect.** C concerns salt concentration between lake portions, which is relevant context but does not compare the two organisms and therefore does not emphasize a difference.
**Faster approach:** For a prompt asking for a difference, immediately eliminate choices that state only a similarity or unrelated facts; choose the answer that explicitly contrasts the two items (e.g., different categories like crustacean vs. bacteria).'),
  ('4560eb68-b3e3-5de5-8299-22443847b9d6', 2, null, '**Choice C is correct.** The notes state that Mastracchio "has performed 9 spacewalks" and Reisman "has performed 3 spacewalks," so both astronauts have performed more than one spacewalk; this directly emphasizes a similarity (both performed multiple spacewalks).
**Choice A is incorrect.** Although true (9 spacewalks vs. 3), this choice emphasizes a difference in total time spent rather than a similarity, so it does not meet the prompt.
**Choice B is incorrect.** This choice restates the definition of EVAs but does not compare the two astronauts or emphasize a similarity between them.
**Choice D is incorrect.** This choice suggests a distinction in terminology between the two when the notes use both terms interchangeably for both astronauts; it implies a difference rather than a similarity.
**Faster approach:** For synthesis questions asking for a similarity, scan the notes for statements that apply to both subjects (words like "both," "each," or identical attributes) and choose the answer that describes that shared attribute.'),
  ('6e919401-82a4-554c-bbb3-11f6f45a87df', 0, null, '**Choice A is correct.** It explicitly links the US Fish & Wildlife Service to the protective action: by limiting human activities in the Tijuana Slough NWR, the Service safeguards the habitat of the light-footed clapper rail. This choice uses two relevant notes (that the Service limits human activities and that the refuge safeguards the rail’s habitat) and presents the causal relationship the student wants to emphasize.
**Choice B is incorrect.** It states that human activities are limited and notes the refuge’s status and location, but it does not identify who (the US Fish & Wildlife Service) is taking that action or explicitly connect the limitation to safeguarding the rail’s habitat.
**Choice C is incorrect.** It gives location and size and mentions the rail, but it does not mention the US Fish & Wildlife Service or any protective action, so it fails to emphasize the Service’s role.
**Choice D is incorrect.** It correctly states the refuge’s purpose in safeguarding the rail and its size, but it does not attribute that protection to the US Fish & Wildlife Service or describe the Service’s actions.
**Faster approach:** Look for the choice that names the actor (US Fish & Wildlife Service) and links that actor to the protective action (limiting human activities); that direct agent-action pairing will be the best answer for emphasizing the agency’s role.'),
  ('97d39abb-a378-5532-ba8a-54334ee9f2ad', 3, null, '**Choice D is correct.** The notes explicitly state that "Sumerian was one of the first languages to be written using the cuneiform script" and that Sumerian was a language in ancient Mesopotamia, so the sentence "Sumerian, an ancient Mesopotamian language, was written using the cuneiform script" directly and accurately identifies a language written in cuneiform.
**Choice A is incorrect.** It mentions ancient Mesopotamian writing and its age but does not identify any specific language written in cuneiform.
**Choice B is incorrect.** It is vague: it claims a language in ancient Mesopotamia used cuneiform but does not name which language, so it fails to identify the language.
**Choice C is incorrect.** It notes the physical evidence (clay tablets) found in present-day Iraq but does not identify any language written on those tablets.
**Faster approach:** Look for the answer choice that names a specific language from the notes (a proper noun like "Sumerian"); choices that are vague or only describe artifacts or dates can be eliminated immediately.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Dec 2025 · Reading & Writing · Module 2
insert into public.tests (id, title, section, description, duration_min, position, published, form_title, module_no)
values ('74b637e7-016c-50f4-a70b-fdf69485768a', 'PeaklyTest Dec 2025 · Reading & Writing · Module 2', 'Reading & Writing', 'Reading & Writing, Module 2 of the Dec 2025 PeaklyTest · 27 questions · 32 minutes', 32, 101, true, 'PeaklyTest Dec 2025 · Reading & Writing', 2)
on conflict (id) do update set title = excluded.title, section = excluded.section, description = excluded.description,
  duration_min = excluded.duration_min, position = excluded.position, form_title = excluded.form_title, module_no = excluded.module_no;
insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('72c09164-7860-59eb-9594-71c7021d9bda', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text with the most logical and precise word or phrase?', '["analogous to", "magnified by", "converted by", "attributed to"]'::jsonb, 1, 'Zygomorphic (bilaterally symmetric) flowers remain open and functional on average 1.1 days longer than actinomorphic (radially symmetric) flowers do. Ruby E. Stephens and colleagues claim that this extended period could be ______ the relatively small pool of potential pollinators available to zygomorphic flowers and the greater chance at successful pollination that remaining open affords them.'),
  ('f73c5485-52ce-562c-921a-d0941da08b9c', '74b637e7-016c-50f4-a70b-fdf69485768a', 'As used in the text, what does the word “accepted” most nearly mean?', '["Shifted", "Approved", "Authorized", "Followed"]'::jsonb, 2, 'The following text is from Charles Dickens’s 1861 novel Great Expectations. The narrator is taking a walk near his home on a damp morning.

On every rail and gate, wet lay clammy, and the marsh mist was so thick, that the wooden finger on the post directing people to our village—a direction which they never <u>accepted</u>, for they never came there—was invisible to me until I was quite close under it.'),
  ('85fbbda1-3523-590f-879b-5d1167268a52', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text with the most logical and precise word or phrase?', '["Foregrounding", "Categorizing", "Anticipating", "Complementing"]'::jsonb, 3, 'Analysis of preserved plants cataloged in the United States Virtual Herbarium indicates that rising temperatures correlate with earlier leaf production, but such specimens represent only brief moments in plants’ overall development. ________ this research with studies involving live plants would enable a fuller understanding of how these observed changes affect plant fitness.'),
  ('d8bf4e0f-f972-5fbc-b977-44a44964b3e4', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text with the most logical and precise word or phrase?', '["evinces", "repudiates", "predates", "eschews"]'::jsonb, 4, 'Although Mistress and Maid, which depicts two women perusing a letter, is atypical of Johannes Vermeer’s genre paintings (scenes of everyday life) in that its subjects are set against a plain background instead of—as in Woman with a Pearl Necklace—a richly detailed one, the painting nonetheless ______ many signature traits of Vermeer’s art, including realistic rendering of natural light.'),
  ('1adcf34e-f6c2-5145-b7a5-e8fabe0857ec', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice best states the function of the underlined sentence in the text as a whole?', '["It contrasts the frequency with which a biological phenomenon has been detected in two categories of organisms.", "It argues that two biological phenomena are more similar than they may initially appear to be.", "It explains why a common perception of a biological process is flawed.", "It indicates a distinction between the mechanics of two kinds of biological processes."]'::jsonb, 5, 'Vertical gene transfer involves the transmission of genetic material from a parent to offspring; horizontal gene transfer, on the other hand, involves the exchange of genetic material between organisms not in a parent-offspring relationship. <u>While horizontal gene transfer is common among prokaryotes—single-</u><u>celled organisms, such as the bacteria Brevundimonas diminuta and Massilia timonae—it has rarely been</u> <u>observed among eukaryotes (multicellular organisms).</u> However, new studies suggest that horizontal gene transfer is more common in eukaryotes than originally thought.'),
  ('a9b89d6b-b647-5acc-9b91-abe01fb34d3f', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice best describes the function of the underlined portion in the text as a whole?', '["It makes a comparison between the past and current rates at which new chemical compounds have entered the scientific literature.", "It emphasizes the point implicitly made earlier in the text that human inefficiency is the primary constraint on the expansion of the chemical space.", "It provides details about the qualification later in the sentence regarding the prospect of cataloging the full range of possible chemical compounds.", "It introduces information that helps explain why the synthesis of superheavy elements has rapidly expanded the chemical space."]'::jsonb, 6, 'The synthesis of novel superheavy elements, such as moscovium (Mc), has led theorists to consider the feasibility of synthesizing all possible chemical compounds. In 2022, Guillermo Restrepo calculated the historical rates at which newly discovered compounds have entered the scientific literature, expanding the “chemical space.” <u>Using a conservative estimate of the number of viable compounds and assuming a</u> <u>doubling of the historical pace of discovery,</u> Restrepo found that under these hypothetical conditions, all potential compounds could be synthesized and documented by 2050.'),
  ('d8734d0f-9351-52b2-8546-c0750b44fecd', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice best describes the function of the underlined sentence in the text as a whole?', '["It explains the origin of Yung’s interest in writing.", "It indicates Yung’s unwillingness to distinguish between reality and fantasy as a child.", "It illustrates the sense of adventure that Yung developed as a child.", "It describes an event in Yung’s life that exemplifies a phenomenon."]'::jsonb, 7, 'The following text is from Yung Wing’s 1909 memoir My Life in China and America. Yung Wing was the first person from China to graduate from a US university.

<u>Little did I realize when in 1845 I wrote, while in the Morrison School, a composition on "An Imaginary</u> <u>Voyage to New York and up the Hudson," that I was to see New York in reality.</u> This incident leads me to the reflection that sometimes our imagination foreshadows what lies uppermost in our minds and brings possibilities within the sphere of realities.'),
  ('2e7a9f09-ef3a-5943-be6c-0d62caaec9b7', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which statement about the prints by Kano and Kawaguchi in Images of Autonomous Matter is best supported by the text?', '["The portrayal of imperfection in the prints illustrates that the artists’ goal was to disrupt the carefully curated nature of most art exhibitions.", "The objects depicted and the manner of depiction render the prints distinct from more conventional works of art.", "The prints showcase how different methods for printing images can offer unique perspectives on stark materials.", "The prints emulate the style of an earlier artistic movement that used simplistic compositions and featured industrial objects."]'::jsonb, 8, 'The prints in Images of Autonomous Matter, part of a traveling exhibition of innovative Japanese art from the 1960s and 1970s, exemplify the interest in creating minimalist images of stark materials, such as steel, that first emerged among Japanese printmakers in the mid-to-late twentieth century. Mitsuo Kano’s close-up of a serrated metal fragment, Soldered Blue, and Tatsuo Kawaguchi’s image of a single corroded staple, which belongs to his Relation—Quality series, are two such works in the exhibit. In their emphasis on the innate qualities of manufactured materials, both prints push traditional boundaries for figurative art.'),
  ('5f7b3ab3-40cc-5f01-9d9f-6753b46af4de', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which statement about the mycelium of the twenty mushroom species is best supported by the text?', '["The mycelium generally maintains temperatures lower than those of the fruited bodies even when considering temperature variations between fruiting and nonfruiting sites.", "The correlation between higher mycelium temperature and greater fruit productivity indicates that successful reproduction may be dependent on thermoregulation in the mycelium.", "Variation in thermoregulation across the mycelium may occur independent of the presence or absence of fruited bodies.", "Temperatures in the fruiting areas of the mycelium are lower than in the nonfruiting areas due to differences in the depth and spread of the mycelium within soil or other organic matter."]'::jsonb, 9, 'Arturo Casadevall et al. have confirmed that twenty mushroom species (including Marasmius capillaris and species from the genus Russula) maintain subambient temperatures in both their fruited bodies and their mycelium (the root-like hyphae from which the fruited bodies grow), though the benefits of this hypothermic behavior are unclear. Noting that relative coldness was more pronounced in fruiting than in nonfruiting sites of the mycelium—a difference that persisted even after fruited bodies were detached—the researchers speculate that thermoregulation in the mycelium may influence reproductive success.'),
  ('475de19e-1f69-5dcf-8327-538f26adc315', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Information in the text best supports which statement about Ptacek et al.’s findings?', '["They suggest that gas permeability testing presents a more reliable indication of concrete durability than compressive strength testing does.", "They bolster the claim that concrete’s susceptibility to damage decreases as its gas permeability increases.", "They call into question the idea that quality of curing conditions directly affects concrete gas permeability but is unrelated to compressive strength.", "They indicate that evaluation of gas permeability is an appropriate addition to concrete quality assessment procedures."]'::jsonb, 10, 'Quality assessments of concrete typically focus almost exclusively on compressive strength as a measure of durability, overlooking other potentially relevant factors. Lisa Ptacek et al. therefore investigated the potential of gas permeability (vulnerability to incursion by gases), which is caused in part by excessive porosity, as a durability indicator. Their measurements and observations revealed that quality of conditions during the concrete curing phase negatively correlates with gas permeability and that high gas permeability values are associated with increased deterioration as concrete surfaces age.'),
  ('e1cbd11b-7714-5a3d-9afa-a8d385fda2fa', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice most effectively uses data from the table to complete the example?', '["common ostrich, which has a higher average mass than the emperor penguin.", "trumpeter swan, which has an average mass of 12.7 kg.", "common ostrich, which has an average mass of 104.0 kg.", "great bustard, which has an average mass below 10 kg."]'::jsonb, 11, '**Bird Species by Average Mass**

| Common name | Average mass (kg) | Capable of flight? |
| Great bustard | 10.6 | Yes |
| Trumpeter swan | 12.7 | Yes |
| Emperor penguin | 31.5 | No |
| Common ostrich | 104.0 | No |

Most bird species that are capable of flight weigh less than a kilogram (kg), which is not surprising considering the burden that extra body weight puts on a flying animal. But not all flying birds are so light, as we can see most clearly in the example of the ______'),
  ('726e9632-0619-5237-8cb1-1f6d073aef07', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice most logically completes the text?', '["be more advantageous for insurers than they are for either current or prospective policyholders.", "benefit policyholders at the expense of nonpolicyholders seeking to acquire policies.", "prevent large increases in premium prices for new policies despite leading to fewer insurers offering such policies in the affected market.", "reduce premium price volatility once policies are in effect but increase risks for policyholders."]'::jsonb, 12, 'In 2004, the US state of North Dakota enacted rate stability regulations (RSRs), constraining insurance companies’ latitude to raise premiums (the periodic fees policyholders pay to maintain insurance policies) after policies are in effect. RSRs are effective at protecting existing policyholders from price volatility, but Naoki Aizawa and Ami Ko note that since dynamic pricing of premiums is an important risk-mitigation tool for insurers, RSRs may lead some insurers to scale back or entirely cease selling new policies in the affected market, thereby reducing the competitive pressure that typically restrains premium prices for new policies. Thus, North Dakota’s RSRs may ______'),
  ('0da09a2c-95fa-5c42-9b19-53e787e31aa1', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which finding, if true, would most directly support Núñez and colleagues’ claim?', '["Yupno speakers typically use their left hand to make temporal gestures regardless of whether the gestures are past oriented or future oriented.", "Some Yupno grammatical structures used when talking about time are also used in Spanish.", "Future-oriented gestures used by Yupno speakers do not, on average, point in the opposite linear direction of past-oriented gestures.", "Yupno speakers were observed making temporal gestures both indoors and outdoors, though with greater frequency when indoors."]'::jsonb, 13, 'Rafael Núñez and colleagues studied how members of the Yupno, an Indigenous group in Papua New Guinea, conceptualize time in both spoken language and gestures. The researchers recorded Yupno speakers explaining certain temporal words and phrases, such as kalip bishop, a past-oriented expression that translates to "past times," and coded each speaker’s manual gestures. Previous research has found a tendency in many cultures to make temporal distinctions along imagined linear axes: for instance, Spanish speakers often refer to the left/right axis to describe events in time. Some researchers believe this tendency is universal, but Núñez and colleagues claim this is not the case.'),
  ('748560f3-a57d-57b9-8a5e-bd110b487bcc', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice most logically completes the text?', '["they tend to sleep more than 15 hours per day in the lab.", "white-throated sparrows have low levels of corticosterone hormones outside of the breeding season in the wild.", "this behavior pattern has not been studied in the lab.", "such data have been collected for white-throated sparrows in laboratory settings but not in the wild."]'::jsonb, 14, 'Studying animals in a laboratory allows variables to be systematically controlled, but removing animals from their wild habitats can affect their behavior and biology in unforeseen ways. Given this, biologists Rebecca M. Calisi-Rodríguez and George E. Bentley examined research on brown-throated three-toed sloths and white-throated sparrows to see whether results from studies in the wild were consistent with the results of studies in the laboratory. Therefore, data showing that brown-throated three-toed sloths tend to sleep fewer than 10 hours per day in the wild would be irrelevant to Calisi-Rodríguez and Bentley’s investigation if ______'),
  ('983f207b-9bcf-52dc-b16e-af9c20346471', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Chen, was known", "Chen, known", "Chen was known", "Chen is known"]'::jsonb, 15, 'Painter Georgette ___ for incorporating everyday objects from her Singaporean environment—such as lanterns, mooncakes, and tropical fruits—into her still-life compositions, was a pivotal figure in the mid-twentieth-century Nanyang art movement, which sought to blend European painting traditions (including still life) with elements of Southeast Asian cultures and art.'),
  ('57d37513-a989-5e08-9862-85e79f5a8029', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["writer Juan Felipe Herrera,", "writer. Juan Felipe Herrera", "writer. Juan Felipe Herrera,", "writer Juan Felipe Herrera"]'::jsonb, 16, 'Streetwide and bitter as hope / strewn between El Salvador and San Francisco." These lines are from a poem by Chicano _____ whose early career as a campesino informs the dialogue on Mexican American politics and identity that unfolds in his work.'),
  ('039a54af-8917-526f-a331-4b0c41d44e25', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["2016), long", "2016) were long", "2016) have long been", "2016), had long been"]'::jsonb, 17, 'Los Angeles–based artist Henry Taylor’s large, vibrant paintings of prominent Black figures such as Olympian Alice Coachman (See Alice Jump, 2011) and artist David Hammons (Hammons meets a hyena on holiday, ______ celebrated by admirers of twenty-first–century portraiture, attracted legions of new fans in 2024 when they were included in a popular Taylor retrospective at the Whitney Museum.'),
  ('bf624702-eb78-50af-a1f0-2abe0321980c', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["Blast, edited", "Blast. Edited", "Blast edited", "Blast; edited"]'::jsonb, 18, 'Among the small magazines animating London’s vibrant literary scene in the early twentieth century was ______ by Wyndham Lewis and featuring artwork by Edward Wadsworth, Frederick Etchells, and Jacob Epstein; fiction by Rebecca West and Ford Madox Ford; and a manifesto penned by Lewis, this magazine publicized the work of influential avant-garde writers and artists of the day.'),
  ('e1d31787-0961-5e85-9e7b-47fcbefeabcd', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["have evoked", "evoke", "evokes", "evoking"]'::jsonb, 19, 'Reena Esmail’s classical composition “Summitless Mountains” incorporates a raag, a melodic framework used in Hindustani classical music, called Raag Chandrakauns. Often, interplay between the raag’s designated vadi and samvadi (the first– and second–most important notes, respectively) and its prescribed melodic sequences ___ an unsettled mood.'),
  ('1014ef6d-3e23-5f9a-9c90-71f0fc40e29e', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text so that it conforms to the conventions of Standard English?', '["are offering", "offer", "offering", "offers"]'::jsonb, 20, 'Archived within the storied libraries of Timbuktu, a West African city prominent during the Songhai Empire, is The Pearls Leading to Accepted Guidance, one of the city’s hundreds of thousands of historical manuscripts, each of which ______ researchers insight into Timbuktu’s tenure as a center of trade and education.'),
  ('f209e859-afc0-54ba-b9b4-a27e94cd0595', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text with the most logical transition?', '["that is,", "rather,", "then,", "still,"]'::jsonb, 21, 'As anthropologist Cristina Grasseni explains, many artisanal cheeses in Italy, such as Castelmagno from Piedmont and Quartirolo Lombardo from Lombardy, are highly valued for their regional authenticity; _____ they are prized for being made using local ingredients and methods typical of their respective geographic regions.'),
  ('b6845a34-eb7b-5683-9328-5bc15cbd5004', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text with the most logical transition?', '["Nevertheless,", "In reality,", "Hence,", "Next,"]'::jsonb, 22, 'The moon Valetudo orbits Jupiter in the same direction that the planet rotates. _______ Valetudo’s orbit is described as prograde. Mneme, another of Jupiter’s moons, orbits in the opposite direction, so its orbit is described with the opposite term: retrograde.'),
  ('6eec8cbe-a72e-55d4-b8d2-28af253b9e0c', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text with the most logical transition?', '["However,", "Granted,", "Lastly,", "Thus,"]'::jsonb, 23, 'For several centuries after the birth of opera in sixteenth-century Florence, Italian remained the default language in which most opera scores were written. _____ opera singers today, such as the soprano Amira Selim, encounter a wide range of Italian terms—from affettuoso (with feeling) to accelerando (at an accelerating tempo)—when following many eighteenth-century opera scores.'),
  ('1106cb49-2a39-57e0-a967-087e6d1f8e08', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text with the most logical transition?', '["Exemplifying this distinction,", "Underscoring this difference,", "Supporting this claim,", "Blurring this line,"]'::jsonb, 24, 'The Rajahnate of Butuan, a sea power based on Mindanao island in the Philippines that reached the height of its influence around 1100 CE, is classified as a thalassocracy. Thalassocracies are generally considered distinct from tellurocracies, or land-based powers. _____ the British Empire (1600s–1900s CE) notably extended its hegemony across both land and sea.'),
  ('9d0b0962-122b-5350-aa62-5ab2439ef147', '74b637e7-016c-50f4-a70b-fdf69485768a', 'Which choice completes the text with the most logical transition?', '["though,", "therefore,", "for example,", "moreover,"]'::jsonb, 25, 'According to climate envelope models, individual organisms that inhabit the coolest areas of their species’ geographic distribution are expected to benefit from a warming climate, while individuals in the warmest areas will struggle. A 2024 University of Arizona study, _____ found that warmer-than-average temperatures resulted in a decrease in growth across all areas of the common piñon tree’s distribution range.'),
  ('03fdf602-ce6c-5c4b-b985-0c89105dbabc', '74b637e7-016c-50f4-a70b-fdf69485768a', 'The student wants to contrast the subject matter of the two prints. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The print by Tana is a black-and-white linocut; by contrast, Burroughs’s is a relief print.", "Burroughs made Birthday Party in 1957, while Tana made Amanzi Amthatha (“The cold water takes him”) later, in 2001.", "Tana’s print expresses an explicitly political point of view, while Burroughs’s depicts a tranquil, everyday scene.", "The scenes depicted in both works were first carved onto a printing block, then stamped onto paper; however, one work is a linocut, while the other is a relief print."]'::jsonb, 26, 'While researching a topic, a student has taken the following notes:

Birthday Party is a 1957 black-and-white linocut print by Black American artist Margaret Burroughs. it depicts a tranquil, everyday scene (a group of children celebrating).

Amanzi Amthatha (“The cold water takes him”) is a 2001 black-and-white linocut print by South African artist Nomathemba Tana.

It features a scene with an explicitly political point of view (a Xhosa warrior fighting British colonial rule).

Relief printing is a technique in which an image is carved onto a printing block, covered in ink or paint, and stamped'),
  ('2583585a-58d8-5536-a056-9c8acb559cee', '74b637e7-016c-50f4-a70b-fdf69485768a', 'The student wants to provide an example of a particle physicist whose research focuses on neutrinos. Which choice most effectively uses relevant information from the notes to accomplish this goal?', '["The research done on geoantineutrinos exemplifies the work particle physicists do to advance our understanding of subatomic particles.", "Neutrinos are a type of subatomic particle that particle physicists are still trying to understand.", "Particle physicist Atsuto Suzuki is known for his discovery of geoantineutrinos.", "By studying geoantineutrinos—to name just one example—particle physicists can learn more about neutrinos."]'::jsonb, 27, 'While researching a topic, a student has taken the following notes:

Atsuto Suzuki is a Japanese particle physicist.
Particle physicists study subatomic particles.
Neutrinos are some of the least understood subatomic particles.
Neutrinos were first discovered in the mid-twentieth century.
Suzuki is known for his discovery of geoantineutrinos.')
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('72c09164-7860-59eb-9594-71c7021d9bda', 3, null, '**Choice D is correct.** The sentence presents an explanation for why zygomorphic flowers remain open longer: it could be because of the small pool of pollinators and the increased chance of successful pollination that a longer open period provides. The phrase "attributed to" precisely expresses causation ("X is attributed to Y" = X is caused by Y), so it fits the logic and grammar of the sentence.
**Choice A is incorrect.** "Analogous to" means "similar to" rather than "caused by," so it fails to express the intended causal relationship between the extended period and the pollinator/benefit factors.
**Choice B is incorrect.** "Magnified by" suggests that the extended period is being amplified by those factors; while close, it implies intensification rather than straightforward causation and is less precise than "attributed to."
**Choice C is incorrect.** "Converted by" means "changed into" and does not make sense contextually—flowers are not being transformed into pollinators or pollination chances—so it is not a plausible fit.
**Faster approach:** Look for a phrase that expresses cause (because/due to/attributed to) rather than similarity or transformation; eliminate choices that mean "similar to" or "changed into."'),
  ('f73c5485-52ce-562c-921a-d0941da08b9c', 3, null, '**Choice D is correct.** The passage says the sign pointed to the village “a direction which they never accepted, for they never came there.” The phrase “for they never came there” explains that people did not go to the village, so “accepted” here most nearly means “followed” (they did not follow the direction to the village).
**Choice A is incorrect.** “Shifted” means moved or changed position; nothing in the sentence suggests the sign or direction was moved.
**Choice B is incorrect.** “Approved” would mean people agreed with the direction, but the contrast with “for they never came there” indicates they did not act on it, not that they withheld approval.
**Choice C is incorrect.** “Authorized” means given official permission; the sentence concerns whether people went that way, not whether permission was granted.
**Faster approach:** Use the immediate explanatory clause (“for they never came there”) as a context clue—replace the word with each choice to see which one makes the sentence logically equivalent; only “followed” fits.'),
  ('85fbbda1-3523-590f-879b-5d1167268a52', 3, null, '**Choice D is correct.** "Complementing this research with studies involving live plants would enable a fuller understanding..." precisely expresses that adding or pairing live-plant studies with herbarium-based analyses would fill gaps left by specimens that capture only brief moments. "Complementing" indicates a collaborative, supplementary relationship that logically produces a more complete understanding of plant fitness.
**Choice A is incorrect.** "Foregrounding" means making something more prominent; it does not convey the idea of combining two kinds of studies to achieve fuller understanding, and the sentence requires a verb meaning "adding to" or "supplementing."
**Choice B is incorrect.** "Categorizing this research with studies involving live plants" is awkward and incorrect in meaning: categorizing groups items rather than combining them to gain a fuller understanding.
**Choice C is incorrect.** "Anticipating this research with studies involving live plants" suggests doing the live-plant studies in advance of the herbarium work, which is neither supported by context nor the intended meaning of supplementing the research.
**Faster approach:** Substitute each option into the sentence and read for meaning: choose the verb that expresses adding or supplementing ("complementing") rather than prominence, ordering, or labeling.'),
  ('d8bf4e0f-f972-5fbc-b977-44a44964b3e4', 0, null, '**Choice A is correct.** The sentence contrasts the painting’s atypical plain background with the fact that it still displays characteristic features of Vermeer’s work; the phrase "including realistic rendering of natural light" indicates the painting does in fact show these traits. "Evinces" means "shows" or "demonstrates," so it fits both grammatically and semantically.
**Choice B is incorrect.** "Repudiates" means "rejects" or "denies," which conflicts with the clause "including realistic rendering of natural light," since the sentence asserts the painting possesses those traits rather than rejects them.
**Choice C is incorrect.** "Predates" means "comes before in time," which is unrelated to the contrast between background style and presence of signature traits; nothing in the sentence refers to chronology.
**Choice D is incorrect.** "Eschews" means "avoids" or "shuns," which would contradict the following phrase listing traits the painting has; the sentence requires a word meaning that the painting exhibits those traits, not that it avoids them.
**Faster approach:** Notice the cue word "including," which signals the subject possesses the listed traits; immediately eliminate words meaning "reject" or "avoid" and choose the synonym for "shows."'),
  ('1adcf34e-f6c2-5145-b7a5-e8fabe0857ec', 0, null, '**Choice A is correct.** The underlined sentence directly contrasts how often horizontal gene transfer is observed in prokaryotes versus eukaryotes, noting that it is common in single-celled prokaryotes (with examples) but rare in multicellular eukaryotes. That comparison of detection frequency between two categories of organisms is the sentence’s primary function in the passage.
**Choice B is incorrect.** The sentence does not argue for similarity between two phenomena; it emphasizes a difference in occurrence rather than making them seem alike.
**Choice C is incorrect.** The sentence does not explain why a perception is flawed; it states an observed difference in frequency but does not claim a common perception is incorrect.
**Choice D is incorrect.** The sentence distinguishes frequency of occurrence, not the mechanics or processes of how gene transfer happens.
**Faster approach:** Quickly identify whether the sentence compares frequency, cause, mechanism, or implication; here the presence of words like "common" and "rarely" signals a frequency contrast, pointing immediately to choice A.'),
  ('a9b89d6b-b647-5acc-9b91-abe01fb34d3f', 2, null, '**Choice C is correct.** The underlined clause lists the specific assumptions Restrepo used (a conservative estimate of viable compounds and an assumed doubling of discovery pace), which qualify the later claim that all potential compounds could be synthesized and documented by 2050. In other words, it supplies the conditions that limit and specify the prospect described in the sentence.
**Choice A is incorrect.** The clause does not compare past and current discovery rates; it states an assumed change (doubling) used in the calculation, not a direct comparison of past vs. present rates.
**Choice B is incorrect.** The clause does not argue about human inefficiency or ascribe a primary constraint to humans; it merely states the numerical assumptions used for the projection.
**Choice D is incorrect.** The clause does not explain why superheavy-element synthesis expanded the chemical space; it describes assumptions for estimating how quickly the cataloging could occur, not causes of expansion.
**Faster approach:** Quickly identify whether the clause states assumptions/conditions, gives causes, or makes comparisons; if it lists conditions for a claim, choose the option about qualifying or providing details for that claim.'),
  ('d8734d0f-9351-52b2-8546-c0750b44fecd', 3, null, '**Choice D is correct.** The underlined sentence recounts a specific incident—writing an imaginary voyage that later became reality—and the next sentence explicitly draws a general conclusion about imagination foreshadowing reality. Thus the sentence functions as a concrete example that exemplifies the phenomenon the author then states.
**Choice A is incorrect.** The sentence does not explain why Yung became interested in writing; it simply reports a particular composition he wrote, not the origin of a writing interest.
**Choice B is incorrect.** The sentence does not claim he couldn’t distinguish reality from fantasy; it notes surprise that an imagined voyage later occurred, not unwillingness to distinguish the two.
**Choice C is incorrect.** While the sentence mentions an imaginative voyage, its purpose is to illustrate the larger point about imagination leading to reality, not primarily to show a childhood sense of adventure.
**Faster approach:** Look for whether the sentence is a specific example followed by a general statement; if so, the sentence likely serves as an illustrative example of a broader phenomenon.'),
  ('2e7a9f09-ef3a-5943-be6c-0d62caaec9b7', 1, null, '**Choice B is correct.** The passage explains that Kano’s close-up of a serrated metal fragment and Kawaguchi’s image of a corroded staple emphasize “the innate qualities of manufactured materials” and “push traditional boundaries for figurative art,” which supports the claim that both the objects depicted and the manner of depiction make these prints distinct from more conventional works.
**Choice A is incorrect.** The passage does not say the artists intended to disrupt the curated nature of exhibitions; it only says the prints push traditional boundaries for figurative art.
**Choice C is incorrect.** The text discusses subject matter and emphasis on materials, not different printing methods or techniques.
**Choice D is incorrect.** The passage locates the works in a mid-to-late twentieth-century Japanese context but does not claim they emulate an earlier movement.
**Faster approach:** Look for language that directly links the artists’ choices to the passage’s main claim (here, “innate qualities” and “push traditional boundaries”) and eliminate choices that introduce unsupported ideas (intentions, techniques, historical emulation).'),
  ('5f7b3ab3-40cc-5f01-9d9f-6753b46af4de', 2, null, '**Choice C is correct.** The passage states that "relative coldness was more pronounced in fruiting than in nonfruiting sites of the mycelium—a difference that persisted even after fruited bodies were detached," which directly supports the idea that variation in thermoregulation across the mycelium can occur independently of whether fruited bodies are present.
**Choice A is incorrect.** The passage does not claim that the mycelium is generally colder than fruited bodies; it reports subambient temperatures in both and emphasizes differences between fruiting and nonfruiting sites within the mycelium.
**Choice B is incorrect.** Although researchers "speculate that thermoregulation in the mycelium may influence reproductive success," the passage gives no evidence of a correlation between higher mycelium temperature and greater fruit productivity.
**Choice D is incorrect.** The passage offers no explanation linking temperature differences to depth or spread of the mycelium in soil or organic matter; that causal claim is not presented.
**Faster approach:** Locate the sentence about the difference persisting after detachment—use it to eliminate options that rely on presence/absence of fruited bodies or introduce unsupported causal explanations.'),
  ('475de19e-1f69-5dcf-8327-538f26adc315', 3, null, '**Choice D is correct.** The passage reports that Ptacek et al. investigated gas permeability "as a durability indicator" and found that "high gas permeability values are associated with increased deterioration as concrete surfaces age," which supports adding gas permeability evaluation to quality-assessment procedures.
**Choice A is incorrect.** The passage says assessments "typically focus almost exclusively on compressive strength" and explores gas permeability as an additional indicator, but it does not claim gas-permeability testing is a more reliable measure than compressive-strength testing.
**Choice B is incorrect.** The passage states the opposite: higher gas permeability is associated with increased deterioration, so susceptibility to damage increases, not decreases, as permeability increases.
**Choice C is incorrect.** The passage explicitly reports that quality of curing "negatively correlates with gas permeability," so it does not call that relationship into question; it also says nothing about whether curing quality is unrelated to compressive strength.
**Faster approach:** Locate the sentence linking gas permeability to deterioration and to assessment; then eliminate choices that contradict that sentence. This pass-and-eliminate strategy works for all similar central-idea questions.'),
  ('e1cbd11b-7714-5a3d-9afa-a8d385fda2fa', 1, null, '**Choice B is correct.** The sentence says that some flying birds are heavier than the typical <1 kg, and asks for an example from the table. The trumpeter swan is marked "Yes" for flight and has an average mass of $12.7$kg, so it clearly supports the point that some flying birds are much heavier than 1 kg.
**Choice A is incorrect.** The common ostrich is 104.0 kg but is listed as not capable of flight, so it cannot serve as an example of a heavy flying bird.
**Choice C is incorrect.** Like A, this choice cites the common ostrich (104.0 kg), which cannot fly, so it does not support the claim about flying birds.
**Choice D is incorrect.** The great bustard is capable of flight but has average mass 10.6 kg, not "below 10 kg," so the factual claim is wrong.
**Faster approach:** Scan the "Capable of flight?" column to find birds marked Yes, then choose the one with the largest mass to illustrate that some flying birds are heavy.'),
  ('726e9632-0619-5237-8cb1-1f6d073aef07', 1, null, '**Choice B is correct.** The passage says RSRs protect existing policyholders from price volatility but may cause insurers to stop selling new policies, "thereby reducing the competitive pressure that typically restrains premium prices for new policies." That predicts a trade-off: current policyholders benefit from stability while prospective buyers (nonpolicyholders) face reduced competition and likely higher prices, which matches choice B.
**Choice A is incorrect.** The passage does not claim insurers benefit more than all policyholders; it describes harms to prospective buyers rather than an advantage to insurers.
**Choice C is incorrect.** It contradicts the passage: reduced competition would not "prevent large increases" in new-policy premiums but rather allow them.
**Choice D is incorrect.** While the passage says RSRs reduce in-effect volatility, it specifically predicts higher costs for prospective policyholders due to less competition, not a general "increase [in] risks for policyholders."
**Faster approach:** Identify the trade-off stated (protection for current holders vs. reduced competition for new buyers) and eliminate choices that contradict that trade-off.'),
  ('0da09a2c-95fa-5c42-9b19-53e787e31aa1', 2, null, '**Choice C is correct.** Núñez and colleagues claim that the tendency to represent time along imagined linear axes is not universal. If Yupno future-oriented gestures do not, on average, point in the opposite linear direction of past-oriented gestures, that directly contradicts the idea of a consistent linear past–future axis and therefore most directly supports the authors’ claim.
**Choice A is incorrect.** That Yupno speakers use their left hand for temporal gestures says nothing about whether they map time onto a left–right linear axis; it could reflect handedness or cultural convention rather than rejection of a linear spatial mapping.
**Choice B is incorrect.** Shared grammatical structures with Spanish would suggest similarities with a culture that uses linear mappings, which would not support the claim that linear time conceptualization is absent or nonuniversal.
**Choice D is incorrect.** Observation of gesture frequency indoors versus outdoors is about context of use, not about whether Yupno conceptualize time along a linear spatial axis, so it does not bear directly on the claim.
**Faster approach:** For evidence/claim questions about whether a pattern is universal, pick the answer that shows the pattern fails (here: past and future do not map onto opposite linear directions), and eliminate choices that are about context or incidental features.'),
  ('748560f3-a57d-57b9-8a5e-bd110b487bcc', 2, null, '**Choice C is correct.** The passage says the authors wanted to compare results from wild and lab studies to see whether they are consistent; if sloth sleeping behavior has not been studied in the lab, then data showing sloths sleep fewer than 10 hours per day in the wild cannot be compared to lab results and so would be irrelevant to that investigation.
**Choice A is incorrect.** If sloths sleep more than 15 hours in the lab, the wild data would be relevant because it would show a discrepancy between wild and lab results, which is exactly what the authors are investigating.
**Choice B is incorrect.** That statement concerns sparrows and hormones, not sloth sleep; it does not make the sloth wild-data irrelevant to a comparison with lab results.
**Choice D is incorrect.** Data missing for sparrows in the wild does not affect whether sloth wild-data can be compared with sloth lab-data; it therefore does not render the sloth wild-data irrelevant.
**Faster approach:** Identify the comparison the authors plan to make (wild vs. lab); then eliminate answer choices that still allow that comparison—choose the option that prevents any lab–wild comparison.'),
  ('983f207b-9bcf-52dc-b16e-af9c20346471', 1, null, '**Choice B is correct.** The sentence requires a nonrestrictive modifier set off by commas: “Painter Georgette Chen, known for incorporating everyday objects..., was a pivotal figure...” The participial phrase “known for incorporating…” modifies the noun and is correctly enclosed by commas, so inserting “Chen, known” yields a grammatically complete sentence with a single main verb “was.”
**Choice A is incorrect.** “Chen, was known” inserts an unnecessary comma between the subject and its verb, creating an ungrammatical interruption.
**Choice C is incorrect.** “Chen was known” would produce two consecutive predicates for the subject ("was known... was a pivotal"), making the sentence awkward and ungrammatical without rewording.
**Choice D is incorrect.** “Chen is known” uses present tense while the surrounding context ("was a pivotal figure" and mid-twentieth-century) requires past tense and consistent verb agreement.
**Faster approach:** Look for whether the phrase is a nonrestrictive modifier needing commas (set it off) or a main verb; if it interrupts between subject and main verb, choose the option that creates a noun plus a comma‑set participial phrase ("Name, known").'),
  ('57d37513-a989-5e08-9862-85e79f5a8029', 0, null, '**Choice A is correct.** The sentence needs a nonrestrictive clause beginning with "whose" to add information about the named individual. Because the writer is already identified as "Juan Felipe Herrera," the clause "whose early career as a campesino informs the dialogue..." is nonessential and must be set off with a comma: "...writer Juan Felipe Herrera, whose..."
**Choice B is incorrect.** A period after "writer" breaks the sentence into a fragment and leaves "Juan Felipe Herrera whose..." without the comma required to set off the nonrestrictive clause.
**Choice C is incorrect.** Putting a period after "writer" still produces a sentence fragment; the comma after the name cannot fix the broken sentence structure that begins with an isolated name.
**Choice D is incorrect.** Omitting the comma before "whose" fails to mark the clause as nonrestrictive; because the name already identifies the person, punctuation is required to set off the additional information.
**Faster approach:** Recognize that a named person followed by a descriptive "whose" clause is typically nonrestrictive and requires a comma before "whose."'),
  ('039a54af-8917-526f-a331-4b0c41d44e25', 0, null, '**Choice A is correct.** The sentence requires a nonfinite participial modifier that can attach to “paintings” without introducing a new finite verb. "..., 2016), long celebrated by admirers of twenty-first–century portraiture, attracted..." supplies the participial phrase "long celebrated by admirers...," which modifies "paintings" and fits the punctuation: the parenthetical closes, the modifier follows, and the main verb "attracted" then completes the clause.
**Choice B is incorrect.** "were long" would introduce a new finite verb phrase immediately after the parenthetical, producing two main verbs for the subject ("were..." and "attracted"), which is ungrammatical.
**Choice C is incorrect.** "have long been" likewise inserts a finite auxiliary verb and creates an extra clause that conflicts with the main clause.
**Choice D is incorrect.** "had long been" also introduces a finite past-perfect verb, improperly adding another main verb instead of a participial modifier.
**Faster approach:** Look for whether the blank needs a participial phrase or a finite verb; if the sentence already has a main verb later, choose the nonfinite (participial) option so you don’t create a second main verb.'),
  ('bf624702-eb78-50af-a1f0-2abe0321980c', 1, null, '**Choice B is correct.** The sentence contains a main clause that begins with "Among the small magazines..." and continues with an appositive phrase that names the magazine and then provides further information about it; punctuation must separate the magazine title from the clause "Edited by Wyndham Lewis..." which is a full participial phrase that completes the appositive. Using a period after the title "Blast." and capitalizing "Edited" creates a separate sentence fragment that functions as a reduced relative clause describing the magazine, but in Standard English the title as a standalone sentence followed by a short descriptor is acceptable here because the descriptor begins a new sentence; the period cleanly closes the appositive and the capitalized "Edited" correctly begins the next sentence, yielding a grammatical sequence: "...was Blast. Edited by Wyndham Lewis and featuring artwork..." This matches the printed-citation punctuation for titles and yields two grammatically complete sentence units when read with the surrounding context.
**Choice A is incorrect.** A comma after the title ("Blast, edited") creates a single continuing clause, but then "edited by Wyndham Lewis..." would be a nonrestrictive participial phrase that needs to attach directly to the noun it modifies; with the intervening "by Wyndham Lewis and featuring..." the sentence becomes awkward and ambiguous, and the comma alone does not provide the necessary syntactic separation here.
**Choice C is incorrect.** Omitting any terminal punctuation after the title ("Blast edited") creates a fused construction with no clear boundary between the title and the participial phrase; Standard English requires punctuation after a short title in this context to mark the separation, so this option is ungrammatical.
**Choice D is incorrect.** A semicolon after the title ("Blast; edited") is used to link two independent clauses of equal weight; here "edited" begins a participial phrase, not an independent clause, so the semicolon is inappropriate and creates a punctuation error.
**Faster approach:** When a title is followed by a phrase that begins with a past-tense participle like "edited," check whether the phrase stands alone as a sentence or modifies the noun; if it starts a new sentence, use a period and capitalize the participle; if it directly modifies the noun within the same clause, use no terminal punctuation or a comma only when the phrase is clearly attached — apply this test to decide punctuation quickly.'),
  ('e1d31787-0961-5e85-9e7b-47fcbefeabcd', 2, null, '**Choice C is correct.** The subject of the clause is the singular noun “interplay,” so it requires a singular present-tense verb. "Elicits" or "evokes" would be appropriate; among the choices, the singular present form "evokes" fits grammatically and preserves the intended meaning that the interplay causes an unsettled mood.
**Choice A is incorrect.** "Have evoked" is plural and past perfect; it does not agree with the singular subject "interplay" and changes the tense.
**Choice B is incorrect.** "Evoke" is the plural base form and does not agree with the singular subject "interplay."
**Choice D is incorrect.** "Evoking" is a present participle and would create a fragment or require an auxiliary verb (for example, "is evoking"); it does not complete the clause as written.
**Faster approach:** Identify the main subject (here, "interplay") and make sure the verb agrees in number; choose the singular present form "evokes."'),
  ('1014ef6d-3e23-5f9a-9c90-71f0fc40e29e', 3, null, '**Choice D is correct.** The phrase "each of which" refers to a singular noun (each manuscript), so it requires a singular, finite verb. "Offers" is the singular third-person present form that correctly completes the clause: "each of which offers researchers insight..."
**Choice A is incorrect.** "Are offering" is plural and progressive; it does not agree with the singular "each."
**Choice B is incorrect.** While "offer" is a present-tense verb, it is the plural form and does not agree with the singular subject "each."
**Choice C is incorrect.** "Offering" is a participle and cannot stand alone as the finite verb required after "which" in this relative clause.
**Faster approach:** Check subject-verb agreement with "each of which" — treat "each" as singular and select the singular verb form ("offers").'),
  ('f209e859-afc0-54ba-b9b4-a27e94cd0595', 0, null, '**Choice A is correct.** The sentence restates and clarifies why those cheeses are valued: the clause that follows explains what “regional authenticity” means. "That is" signals a clarification or restatement, so "...are highly valued for their regional authenticity; that is, they are prized for being made using local ingredients and methods..." creates a clear, logical connection.
**Choice B is incorrect.** "Rather" indicates contrast or correction, but the second clause does not contradict the first; it explains it, so "rather" is inappropriate.
**Choice C is incorrect.** "Then" suggests sequence or consequence in time, which doesn’t fit a restatement or clarification.
**Choice D is incorrect.** "Still" implies concession or contrast, which conflicts with the explanatory relationship between the clauses.
**Faster approach:** Look for whether the second clause clarifies (use "that is"), contrasts (use "rather/still"), or shows time/sequence (use "then"); choose the transition that matches.'),
  ('b6845a34-eb7b-5683-9328-5bc15cbd5004', 2, null, '**Choice C is correct.** The second sentence explains the consequence of Valetudo’s direction of orbit: because it orbits in the same direction as Jupiter’s rotation, it is described as prograde. "Hence," signals that what follows is a logical result of the preceding statement, so it fits the causal relationship between the two sentences.
**Choice A is incorrect.** "Nevertheless," indicates a contrast or exception; no contrast is being introduced, so it does not match the relationship between the sentences.
**Choice B is incorrect.** "In reality," suggests a correction or clarification of a misconception, but the second sentence is stating a direct consequence rather than correcting the first sentence.
**Choice D is incorrect.** "Next," indicates sequence in time or steps; the second sentence gives a reason, not the next item in a list, so this transition is inappropriate.
**Faster approach:** Identify whether the second sentence expresses cause/result (look for words like "is described as" or explanations); if so, choose a causal transition such as "hence," "therefore," or "thus."'),
  ('6eec8cbe-a72e-55d4-b8d2-28af253b9e0c', 3, null, '**Choice D is correct.** The first clause establishes a historical fact (that Italian was the default language for opera scores); the second clause explains a present consequence of that fact (that opera singers today encounter many Italian terms). The transition "Thus," correctly signals this cause-and-effect relationship: because scores were written in Italian, singers encounter Italian terms.
**Choice A is incorrect.** "However," signals contrast, but the two clauses do not contradict one another; they describe a historical practice and its present result, so contrast is inappropriate.
**Choice B is incorrect.** "Granted," introduces a concession, which does not fit the explanatory relationship between the clauses.
**Choice C is incorrect.** "Lastly," indicates sequence or finality, which is not called for here; the sentence is explaining a consequence rather than listing items.
**Faster approach:** Identify whether the second clause states a result (use "Thus/Therefore"), a contrast (use "However"), a concession (use "Granted"), or a sequence (use "Lastly").'),
  ('1106cb49-2a39-57e0-a967-087e6d1f8e08', 3, null, '**Choice D is correct.** The sentence before the blank sets up a contrast between sea-based thalassocracies and land-based tellurocracies; the clause that follows notes that the British Empire "notably extended its hegemony across both land and sea," which weakens a strict separation. "Blurring this line," directly signals that the British case makes the distinction less clear, so it is the most logical transition.
**Choice A is incorrect.** "Exemplifying this distinction" would mean the British Empire illustrates the clear difference between sea and land powers, but the example given (control of both land and sea) does the opposite.
**Choice B is incorrect.** "Underscoring this difference" likewise suggests the example reinforces a separation, which contradicts the stated fact that the British spanned both domains.
**Choice C is incorrect.** "Supporting this claim" is vague and implies the British example backs up the prior assertion; it does not, because the British case undermines a strict separation.
**Faster approach:** Look at the example after the blank—if it contradicts the preceding generalization, pick a transition that signals weakening or contrast (words like "blurring," "challenging," or "complicating").'),
  ('9d0b0962-122b-5350-aa62-5ab2439ef147', 0, null, '**Choice A is correct.** The sentence before the blank describes a contrast: models predict benefits in cool areas and struggles in warm areas. The study’s finding — a decrease in growth across all areas — directly contradicts that contrast. The transitional adverb "though" signals this kind of contrast and fits grammatically: "A 2024 University of Arizona study, though, found..."
**Choice B is incorrect.** "Therefore" indicates a logical consequence, but the study’s finding does not follow from the models; it conflicts with them, so "therefore" is wrong.
**Choice C is incorrect.** "For example" would introduce an illustration of the prior claim, but the study does not illustrate the models’ prediction — it contradicts it.
**Choice D is incorrect.** "Moreover" adds supporting information, which is inappropriate because the study’s result opposes, rather than reinforces, the preceding statement.
**Faster approach:** Identify whether the second clause supports or opposes the first; pick a transition that signals the same relationship (contrast → choose a contrast word like "though").'),
  ('03fdf602-ce6c-5c4b-b985-0c89105dbabc', 2, null, '**Choice C is correct.** The notes explicitly state that Tana’s Amanzi Amthatha “features a scene with an explicitly political point of view (a Xhosa warrior fighting British colonial rule),” while Burroughs’s Birthday Party “depicts a tranquil, everyday scene (a group of children celebrating).” Those descriptions directly contrast the subject matter of the two prints: one political, the other everyday and peaceful.
**Choice A is incorrect.** It misrepresents the notes: both prints are described as black-and-white linocuts, and linocut is a type of relief print, so the contrast stated is false.
**Choice B is incorrect.** The dates compare when the works were made, not their subject matter; the prompt asks to contrast subject matter.
**Choice D is incorrect.** While relief printing is described, the choice falsely implies one is linocut and the other is merely a relief print; the notes identify both as linocuts.
**Faster approach:** Scan the notes for words that describe the content or tone (for example, “political,” “tranquil,” “everyday”) and choose the option that directly contrasts those descriptions.'),
  ('2583585a-58d8-5536-a056-9c8acb559cee', 2, null, '**Choice C is correct.** The notes state that "Atsuto Suzuki is a Japanese particle physicist" and that "Suzuki is known for his discovery of geoantineutrinos," directly providing a named particle physicist whose work involves neutrinos; this choice most effectively uses those relevant facts to give the requested example.
**Choice A is incorrect.** This statement describes geoantineutrino research generally rather than providing a specific particle physicist as an example, so it doesn’t meet the prompt’s requirement to name a researcher.
**Choice B is incorrect.** While true according to the notes, it restates background about neutrinos rather than giving an example of a particle physicist who researches them.
**Choice D is incorrect.** This explains why studying geoantineutrinos is useful but does not name a specific particle physicist whose research focuses on neutrinos, so it fails to provide the requested example.
**Faster approach:** Look for the answer that names a person and links that person to neutrino research—if present, that choice will directly fulfill the prompt.')
on conflict (question_id) do update set correct_index = excluded.correct_index, correct_answers = excluded.correct_answers,
  explanation = excluded.explanation;

-- PeaklyTest Dec 2025 · Math · Module 1
