insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('5c164f99-9b58-5694-97a3-fcd38df932bf', '616f1be7-470b-5378-9c85-59e3290ee7e6', 'The function $f$ is defined by the equation $f(x) = 5x - 6$. What is the value of $f(x)$ when $x = 10$?', '[]'::jsonb, 1, null),
  ('a3025efb-1999-54e9-ae37-06324134b8c2', '616f1be7-470b-5378-9c85-59e3290ee7e6', 'On a certain day in June, the lowest recorded wind speed in a town was $5$ miles per hour (mph) and the highest recorded wind speed was $14$ mph. Which inequality is true for all values of $w$, where $w$ represents any wind speed, in mph, recorded in the town on this day?', '["$w \\le 5$", "$w \\le 9$", "$w \\ge 14$", "$5 \\le w \\le 14$"]'::jsonb, 2, null),
  ('643077b8-8587-5809-a919-7705cb83d5de', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**What value of** $p$ **is the solution to the equation** $4p - 5p = 14$**?**', '["$-14$", "$-\\frac{1}{14}$", "$\\frac{1}{14}$", "$14$"]'::jsonb, 3, null),
  ('551ff3c4-ab4c-5956-ab35-9b1677dd42c0', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**A polygon with** $22$ **sides has a perimeter of** $131$ **inches. The length of one side is** $5$ **inches. The** **other** $21$ **sides have equal lengths. What is the length, in inches, of one of the** $21$ **sides with equal** **lengths?**', '[]'::jsonb, 4, null),
  ('b3269b3a-e562-575c-8072-a995dfeeee77', '616f1be7-470b-5378-9c85-59e3290ee7e6', 'To purchase a used car at a total price of $13,000$ dollars, a one-time down payment is required, and then fixed monthly payments are made for the remaining amount owed for the car. The equation $13,000 = 2,600 + 260t$ represents this situation, where $t$ is the number of fixed monthly payments that are made. Which of the following is the best interpretation of $260$ in this context?', '["The amount, in dollars, of the down payment", "The amount, in dollars, of each fixed monthly payment", "The total amount, in dollars, paid for the car after $t$ fixed monthly payments", "The total number of fixed monthly payments"]'::jsonb, 5, null),
  ('d440c211-3f02-510f-afb5-cba7b0d11777', '616f1be7-470b-5378-9c85-59e3290ee7e6', 'If $3 - 2x = 42$, what is the value of $\frac{1}{6}(3 - 2x)$?', '["$6$", "$7$", "$42$", "$252$"]'::jsonb, 6, null),
  ('3f7b05a8-8ced-5213-9b0c-5da7afae6869', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**The ratio** $72$ **to** $m$ **is equivalent to the ratio** $4$ **to** $24$**. What is the value of** $m$**?**', '["$3$", "$24$", "$144$", "$432$"]'::jsonb, 7, null),
  ('422e54c6-e330-5237-863a-df5d26f15a5c', '616f1be7-470b-5378-9c85-59e3290ee7e6', '$(z + 4)(z - 6) = 0$
What are all possible solutions to the given equation?', '["$-4$ and $-6$", "$-4$ and $6$", "$4$ and $-6$", "$4$ and $6$"]'::jsonb, 8, null),
  ('9f9597b4-192f-5948-9955-90481f3ed876', '616f1be7-470b-5378-9c85-59e3290ee7e6', '$7x - 8y = x^{2}$
$7x - 8y = 36$
A solution to the given system of equations is $(x,y)$, where $x$ is positive. What is the value of $x$?', '[]'::jsonb, 9, null),
  ('b479fd70-5aba-5e56-8c51-ccab5aac1292', '616f1be7-470b-5378-9c85-59e3290ee7e6', '', '["$9x + 3y = 90$", "$9x + 3y = 3$", "$3x + 9y = 90$", "$3x + 9y = 3$"]'::jsonb, 10, '**The table shows four values of** $x$ **and their corresponding values of** $y$**. There is a linear relationship** **between** $x$ **and** $y$**. Which of the following equations represents this relationship?**

| $x$ | $y$ |
| $-6$ | $48$ |
| $-3$ | $39$ |
| $3$ | $21$ |
| $6$ | $12$ |'),
  ('be00f406-9db0-53fb-a738-cd5f9003ef74', '616f1be7-470b-5378-9c85-59e3290ee7e6', 'Which statement is true based on the table?', '["The Group A data set was identical to the Group B data set.", "Group B contained the tallest participant.", "The heights of the men in Group B had a larger spread than the heights of the men in Group A.", "The median height of Group B is larger than the median height of Group A."]'::jsonb, 11, '**The results of two independent surveys are shown in the table below.**

| Men’s Height |  |  |  |
| **Group** | **Sample size** | **Mean (centimeters)** | **Standard deviation (centimeters)** |
| A | 2,500 | 186 | 12.5 |
| B | 2,500 | 186 | 19.1 |'),
  ('a3a6fe15-a740-56dc-a8ed-e8eaeb7aefdc', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**Real estate company offers a series of three webinars.** $3,125$ **people attended the first webinar.** $56%$ **of the people who attended the first webinar attended the second webinar, and** $26%$ **of the** **people who attended the first and second webinars attended the third webinar. How many people** **attended all three webinars?**', '[]'::jsonb, 12, null),
  ('9bca1556-fb69-5c09-b045-5e12f494d300', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**The scatterplot shows the relationship between two variables,** $x$ **and** $y$**. A line of best fit for the** **data is also shown. Which of the following is closest to the difference between the** $y$**-coordinate** **of the data point with** $x = 1$ **and the** $y$**-value predicted by the line of best fit at** $x = 1$**?**', '["$1$", "$2$", "$5$", "$12$"]'::jsonb, 13, '![figure](/q/dec25/001.webp)'),
  ('013c02dd-a442-5f87-af93-5bd21e14be1a', '616f1be7-470b-5378-9c85-59e3290ee7e6', 'What is the value of $x$?', '[]'::jsonb, 14, '![figure](/q/dec25/002.webp)

**Intersecting lines** $r$**,** $s$**, and** $t$ **are shown below.**'),
  ('639cf014-8b74-5748-b935-0ecf0c4a4aed', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**The expression** $15x(x^{2} + 9)$ **is equivalent to** $ax^{b} + cx$**, where** $a$**,** $b$**, and** $c$ **are constants. What is the** **value of** $abc$**?**', '[]'::jsonb, 15, null),
  ('336dfe0c-a0c2-5f52-8419-21d5a7af91d8', '616f1be7-470b-5378-9c85-59e3290ee7e6', 'In the $xy$-plane, an equation of circle $R$ is $(x + 8)^{2} + (y + 19)^{2} = 100$. Circle $S$ is obtained by shifting circle $R$ to the right 3 units. An equation defining circle $S$ is $(x + h)^{2} + (y + k)^{2} = 100$, where $h$ and $k$ are constants. What is the value of $h$?', '[]'::jsonb, 16, null),
  ('158e0bc1-4cc0-5d4c-865a-ea5a3ed8910e', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**On January** $1$**, there were** $237$ **views of a video posted on a social media site. Every** $2$ **days after** **January** $1$**, the number of views of the video had increased by** $70%$ **of the number of views** $2$ **days** **earlier. The function** $f$ **gives the predicted number of views** $x$ **days after January** $1$**. Which** **equation defines** $f$**?**', '["$f(x) = 237(0.70)^{x}$", "$f(x) = 237(0.70)^{x/2}$", "$f(x) = 237(1.70)^{x}$", "$f(x) = 237(1.70)^{x/2}$"]'::jsonb, 17, null),
  ('3c068abe-776d-5012-ac52-891f424b3b7d', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**Quadrilaterals** $PQRS$ **and** $WXY Z$ **are similar, where** $P$**,** $Q$**, and** $R$ **correspond to** $W$**,** $X$**, and** $Y$**,** **respectively. The measure of** $\angle S$ **is** $135°$**,** $PS = 45$**, and** $WZ = 9$**. What is the measure of** $\angle Z$**?**', '["$5°$", "$27°$", "$45°$", "$135°$"]'::jsonb, 18, null),
  ('4d347db4-8434-5412-93b1-8a6a7f0b2230', '616f1be7-470b-5378-9c85-59e3290ee7e6', '$f(x) = 4x^{2} + 16x + 22$
The function $f$ is defined by the given equation. The function $h$ is defined by $h(x) = f(x) + 9$. What is the minimum value of $h(x)$?', '["$31$", "$15$", "$7$", "$0$"]'::jsonb, 19, null),
  ('73020158-876a-53e7-a75a-f1cfc985404f', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**The solution to the given system of equations is** $(x,y)$**. What is the value of** $5x + 8y$**?**
$7(5x) + 9(8y) = 189$
$7(5x) - 9(8y) = -819$', '["$-101$", "$5$", "$11$", "$56$"]'::jsonb, 20, null),
  ('7e04f981-4685-58ef-828d-c31929b0965c', '616f1be7-470b-5378-9c85-59e3290ee7e6', 'For the polynomial function, when $f(x)$ is divided by $x - 8$, the remainder is $9$. Which of the following must be true about the graph of $y = f(x)$ in the $xy$-plane?', '["It passes through the point $(9,-8)$.", "It passes through the point $(-8,9)$.", "It passes through the point $(9,8)$.", "It passes through the point $(8,9)$."]'::jsonb, 21, null),
  ('0b61c575-9141-54a4-ad47-f68b9dc3c456', '616f1be7-470b-5378-9c85-59e3290ee7e6', '**In the given equation,** $k$ **and** $m$ **are constants. The equation has infinitely many solutions. What is** **the value of** $m$**?**
$\frac{-22x - 29 + m}{2} = k(x + 5)$', '["$39$", "$-11$", "$-26$", "$-81$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
