insert into public.questions (id, test_id, prompt, options, position, passage) values
  ('dc9a85b8-a1f2-5796-83a4-7072e06f4730', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '**In triangle** $JKL$**, the measures of** $\angle K$ **and** $\angle L$ **are each** $51$**. What is the measure of** $\angle J$**, in degrees?** **(Disregard the degree symbol when entering your answer.)**', '[]'::jsonb, 1, null),
  ('08e9722e-59f4-506b-954b-857d06bc0441', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'The table shows three values of $x$ and their corresponding values of $y$ for the equation $y = 7(2)^{x} + 8$. In the table, $a$ is a constant. What is the value of $a$?', '["$120$", "$64$", "$56$", "$50$"]'::jsonb, 2, '| $x$ | $y$ |
| 1 | 22 |
| 2 | 36 |
| 3 | $a$ |'),
  ('351c1bf0-aeed-558c-9ad2-9f71e200912c', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '**For a party,** $65$ **hamburger buns are needed. Hamburger buns are sold in packages of** $12$**. What is** **the minimum number of packages that should be bought for the party?**', '[]'::jsonb, 3, null),
  ('af0474e2-1d76-5bd8-a980-5bb56509758f', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'The height of a right circular cylinder is $36$ inches, and the circumference of its base is $360$ inches. Which expression represents the total surface area, in square inches, of the cylinder?', '["$(36)(360) + 2π (\\frac{180}{π})^{2}$", "$(36)(360) + π (\\frac{180}{π})^{2}$", "$π (\\frac{180}{π})^{2} (36)$", "$(36)(360)$"]'::jsonb, 4, null),
  ('e878562e-dff2-5554-a336-75af5edd696c', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'A researcher is designing a study to investigate the average number of hours students at a high school spend reading per day. The researcher will report an estimated average number of hours students at the high school spend reading per day with an associated margin of error. The researcher is considering using a random sample of either $90$ or $180$ students from the high school. Which of the following would be the most likely effect of using the larger random sample compared to the smaller random sample?', '["The reported margin of error would be lower.", "The reported margin of error would be higher.", "The reported average number of hours would be lower.", "The reported average number of hours would be higher."]'::jsonb, 5, null),
  ('09fe6392-caeb-5268-8bbc-fd906dbb19e1', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '**The solution to the given system of equations is** $(x,y)$**. What is the value of** $8y$**?**
$2x + 5y = 260$
$-2x + 3y = 260$', '["$0$", "$65$", "$260$", "$520$"]'::jsonb, 6, null),
  ('a15386f2-cf96-598e-b1d7-6f9f3014e10b', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '**If** $\frac{9x}{2} - 11 = \frac{45}{2} - 11$**, what is the value of** $9x$**?**', '["$5$", "$10$", "$45$", "$54$"]'::jsonb, 7, null),
  ('b96f043f-b5e2-5d78-8fb8-1a7951fd7288', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'The solution to the given system of equations is $(x,y)$. What is the value of $x + y$?
$8x - 7y = 5$
$4x + y = 8$', '[]'::jsonb, 8, null),
  ('00299247-ff6b-5f41-82c3-eef6b90b025a', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'A group of biology students conducted an experiment to study the relationship between a person’s femur length and the person’s height. The given equation describes the relationship between the length $L$, in inches, of a student’s femur and the student’s estimated height $H$, in inches, for the students in the group. Which of the following is the best interpretation of $2.419$ in this context?
$H = 2.419L + 22.83$', '["The increase in a student’s estimated height, in inches, for each increase of 1 inch in the student’s femur length", "The increase in a student’s femur length, in inches, for each increase of 1 inch in the student’s estimated height", "The increase in a student’s femur length, in inches, for each increase of $22.83$ inches in the student’s estimated height", "The estimated height, in inches, of a student whose femur has a length of $L$ inches"]'::jsonb, 9, null),
  ('4891c60d-5be7-5482-ae06-1baf82b59fb1', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '$0.10x + 0.20y = 0.17(x + y)$
The equation gives a volume $x$, in gallons, of a $10%$ saltwater solution that could be mixed with a volume $y$, in gallons, of a $20%$ saltwater solution to produce a $17%$ saltwater solution. According to this equation, what volume, in gallons, of the $20%$ saltwater solution could be mixed with $75.0$ gallons of the $10%$ saltwater solution to produce a $17%$ saltwater solution? (Assume that the volume of the mixture is the sum of the volumes of the two solutions before they were mixed.)', '[]'::jsonb, 10, null),
  ('b4f6da83-07f4-584e-9aeb-31318e63b572', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '$0.1242$ is $0.09%$ of the number $b$. The number $b$ is $25%$ of the number $c$. What is the value of $c$?', '[]'::jsonb, 11, null),
  ('5f639167-7cc1-57ab-9849-6eeb3569fa22', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'In the $xy$-plane, line $h$ passes through the point $(0,0)$ and is perpendicular to the line represented by the equation $-3x + y = 20$. If line $h$ also passes through the point $(18,t)$, what is the value of $t$?', '["$-54$", "$-6$", "$6$", "$54$"]'::jsonb, 12, null),
  ('491a15a6-4611-5ea7-a3b7-a7a5a22bf4d1', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'Which system of linear equations has no solution?', '["$-3x + 9y = -2$\n\n$3x - 9y = 2$", "$3x - 9y = 2$\n\n$4x + 10y = 3$", "$3x - 9y = 2$\n\n$-9x + 27y = -6$", "$-3x + 9y = 2$\n\n$6x - 18y = 4$"]'::jsonb, 13, null),
  ('a0690650-254e-5af2-a183-b69481aff2ab', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '$f(x) = 6000(1.003)^{2x}$
The given function $f$ models the balance of a bank account, in dollars, $x$ years after it is opened. Which statement is the best interpretation of $(1.003)^{2x}$?', '["Every 6 months, the balance increases by about \\$3.", "Every 2 years, the balance increases by about \\$3.", "At the end of every 6-month interval, the balance increases by about $0.3%$ of the balance at the beginning of the 6-month interval.", "At the end of every 2-year interval, the balance increases by about $0.3%$ of the balance at the beginning of the 2-year interval."]'::jsonb, 14, null),
  ('13b6ece4-5c46-5dce-b419-204777b68435', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '**Which of the following is a factor of the expression** $2x^{2} + (18r + 5)x + 45r$**, where** $r$ **is a nonzero** **constant?**
I. $x + 9r$
II. $2x + 5$', '["I only", "II only", "I and II", "Neither I nor II"]'::jsonb, 15, null),
  ('a1fa56ee-c785-52b5-b5da-2d75f8e617fe', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '**The equation** $5∣x - 8∣ = k$**, where** $k$ **is a constant, has exactly one solution. Which of the following** **could be the value of** $\frac{k}{5}$**?**', '["$-8$ or $8$", "$-8$ only", "$0$ only", "$8$ only"]'::jsonb, 16, null),
  ('27a17fc4-c57c-544f-9726-283cecc5b6b7', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'Given the equation $8∣7 - x∣ + 2 = 82$, what is the sum of the solutions?', '["14", "10", "-3", "-14"]'::jsonb, 17, null),
  ('8c6a1457-7d80-5585-a401-9ab2cd1d4b79', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'The quadratic function $g$ models the depth, in meters, below the surface of the water of a Weddell seal $t$ minutes after the seal entered the water during a dive. The function estimates that the seal reached its maximum depth of $396.8$ meters $8$ minutes after it entered the water and then reached the surface of the water $16$ minutes after it entered the water. Based on the function, what was the estimated depth, to the nearest meter, of the seal $11$ minutes after it entered the water?', '[]'::jsonb, 18, null),
  ('70555fa5-4cb4-5fc8-b64c-1949cd19c09f', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'In triangle $XY Z$, the measure of angle $X$ is $90°$. Point $W$ lies on segment $XZ$, and segment $WV$ is perpendicular to segment $Y Z$ at point $V$. The length of segment $WV$ is $668$, and the length of segment $ZV$ is $501$. What is the value of $\tan Z$?', '["$\\frac{3}{5}$", "$\\frac{3}{4}$", "$\\frac{4}{5}$", "$\\frac{4}{3}$"]'::jsonb, 19, null),
  ('b7406481-235c-558f-8fc1-56b5a47fccf1', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'A scientist studied the effects of mixing two chemicals, chemical A and chemical B, by gradually adding more of each chemical to a mixture of the two chemicals. At the start of the study, the mass of chemical A in the mixture was equal to the mass of chemical B in the mixture. From the start of the study to the end of the study, the mass of chemical A in the mixture increased by $2,600%$ and the mass of chemical B in the mixture increased by $380%$. At the end of the study, approximately how many times greater was the mass of chemical A in the mixture than the mass of chemical B in the mixture?', '["$29.80$", "$22.20$", "$6.84$", "$5.63$"]'::jsonb, 20, null),
  ('2fe5583e-5c33-59b5-af84-e91dd584db3c', '3d191b44-e829-5171-a6bf-1653aafcc7b8', '$r^{2} - qr = 8r - 87$
In the given equation, $q$ is an integer constant. The given equation has no real solutions. What is the largest possible value of $q$?', '[]'::jsonb, 21, null),
  ('b96d65e2-18a1-58bd-8685-7b93367e5f12', '3d191b44-e829-5171-a6bf-1653aafcc7b8', 'An isosceles right triangle has a perimeter of $34 + 34\sqrt{2}$ inches. What is the length, in inches, of one leg of this triangle?', '["$17$", "$17\\sqrt{2}$", "$34$", "$34\\sqrt{2}$"]'::jsonb, 22, null)
on conflict (id) do update set test_id = excluded.test_id, prompt = excluded.prompt, options = excluded.options,
  position = excluded.position, passage = excluded.passage;
insert into public.question_keys (question_id, correct_index, correct_answers, explanation) values
  ('dc9a85b8-a1f2-5796-83a4-7072e06f4730', null, array['78']::text[], '**The correct answer is 78.** In any triangle, the measures of the three interior angles add to $180$ degrees. Given that $\angle K = 51$ and $\angle L = 51$, compute $\angle J = 180 - 51 - 51 = 180 - 102 = 78$ degrees.
**Faster approach:** Immediately subtract the sum of the two equal angles from $180$: $180 - 2 \times 51 = 180 -$ $102 = 78$. This direct use of the triangle-angle-sum property works for any similar problem with two known angles.'),
  ('08e9722e-59f4-506b-954b-857d06bc0441', 1, null, '**Choice B is correct.** Substitute $x = 3$ into $y = 7(2)^{x} + 8$. Since $2^{3} = 8$, $y = 7 \cdot 8 + 8 = 56 + 8 = 64$, so $a = 64$ .
**Choice A is incorrect.** $120$ is too large; it would correspond to $7(2)^{x} = 112$, which does not occur for integer $x$ here.
**Choice C is incorrect.** $56$ is the value of $7(2)^{3}$ but omits the added $8$ in the formula, so it is not $y$.
**Choice D is incorrect.** $50$ is not produced by substituting any of the given $x$ values into the function $7(2)^{x} + 8$ .
**Faster approach:** For this skill, directly substitute the given $x$ into the rule $y = 7(2)^{x} + 8$ (or recognize that each increment of $x$ doubles the $7(2)^{x}$ term) to get the value quickly.'),
  ('351c1bf0-aeed-558c-9ad2-9f71e200912c', null, array['6']::text[], '**The correct answer is 6.** Each package contains 12 buns, so buying $n$ packages yields $12n$ buns. We need $12n \ge 65$. Dividing both sides by 12 gives $n \ge 65/12 \approx 5.416…$. Because $n$ must be a whole number of packages, the smallest integer $n$ that satisfies this inequality is $6$. With 6 packages you get $6 \times 12 = 72$ buns, which is at least 65; 5 packages give only 60 buns, which is insufficient.
**Faster approach:** Divide 65 by 12 and round up (take the ceiling). $65/12 \approx 5.416$, so round up to 6 packages.'),
  ('af0474e2-1d76-5bd8-a980-5bb56509758f', 0, null, '**Choice A is correct.** The lateral surface area is circumference × height = $360 \cdot 36$. The two circular bases together have area $2πr^{2}$, and from $360 = 2πr$ we get $r = \frac{180}{π}$. So the total surface area is $360 \cdot 36 +$
$2$
$2π (\frac{180}{π})$, which matches choice A.
$2$
**Choice B is incorrect.** It uses $π (\frac{180}{π})$ for the bases, which is the area of only one base, not both.
$2$
**Choice C is incorrect.** It gives $π (\frac{180}{π}) (36)$, which multiplies a base area by the height; that is not a surface-area formula for a cylinder.
**Choice D is incorrect.** It includes only the lateral area $360 \cdot 36$ and omits the areas of the two bases. **Faster approach:** Use lateral area = (circumference)(height) and base area = $πr^{2}$ with $r = \frac{\text{circumference}}{2π}$; then add lateral + $2\times$base.'),
  ('e878562e-dff2-5554-a336-75af5edd696c', 0, null, '**Choice A is correct.** The margin of error for a sample mean is proportional to the standard error, which is $\text{SE} = \frac{σ}{\sqrt{n}}$ (or estimated with $s/\sqrt{n}$). Increasing the sample size from $90$ to $180$ increases $n$, so $\sqrt{n}$ increases and the standard error (and thus the margin of error) decreases. Therefore the reported margin of error would be lower with the larger sample.
**Choice B is incorrect.** A larger sample reduces sampling variability and therefore reduces the margin of error; it does not increase it.
**Choice C is incorrect.** Changing the sample size does not systematically change the sample mean (unless sampling is biased). The average could be higher or lower by chance, but increasing $n$ does not guarantee a lower reported average.
**Choice D is incorrect.** For the same reason as C: increasing sample size improves precision but does not consistently raise the estimated average.
**Faster approach:** Remember that margin of error scales like $1/\sqrt{n}$ — doubling sample size reduces margin of error by a factor of $1/\sqrt{2}$, so a larger sample gives a smaller margin of error.'),
  ('09fe6392-caeb-5268-8bbc-fd906dbb19e1', 3, null, '**Choice D is correct.** Adding the two equations eliminates $x$: $(2x + 5y) + (-2x + 3y) = 260 + 260$ gives $8y = 520$, so $8y = 520$, which matches choice D.
**Choice A is incorrect.** $0$ would mean $8y = 0$, so $y = 0$, which does not satisfy the given equations (substituting $y = 0$ into $2x + 5y = 260$ gives $x = 130$, but that fails the second equation).
**Choice B is incorrect.** $65$ would mean $8y = 65$, so $y = 65/8$, which does not satisfy both original equations when checked.
**Choice C is incorrect.** $260$ would mean $8y = 260$, so $y = 32.5$, which does not satisfy both equations; the correct value from adding is $520$.
**Faster approach:** Add the two equations to cancel $x$ immediately and solve for $8y$ in one step.'),
  ('a15386f2-cf96-598e-b1d7-6f9f3014e10b', 2, null, '**Choice C is correct.** Starting with $\frac{9x}{2} - 11 = \frac{45}{2} - 11$, add 11 to both sides to get $\frac{9x}{2} = \frac{45}{2}$. Multiply both sides by 2 to obtain $9x = 45$, so the value of $9x$ is 45.
**Choice A is incorrect.** If $9x$ were 5, then $\frac{9x}{2} = \frac{5}{2}$, which does not equal $\frac{45}{2}$ from the equation; thus 5 is not valid.
**Choice B is incorrect.** If $9x$ were 10, then $\frac{9x}{2} = 5$, not $\frac{45}{2}$, so 10 is not a solution.
**Choice D is incorrect.** If $9x$ were 54, then $\frac{9x}{2} = 27$, which is not $\frac{45}{2}$, so 54 is not correct.
**Faster approach:** Add 11 to both sides immediately to remove the constant, then clear the denominator by multiplying by 2 — this two-step process (undo addition, then undo division) works for all linear equations of this form.'),
  ('b96f043f-b5e2-5d78-8fb8-1a7951fd7288', null, array['35/12']::text[], '**The correct answer is 35/12.** Solve the system. From the second equation, $y = 8 - 4x$. Substitute into the first: $8x - 7(8 - 4x) = 5$, so $8x - 56 + 28x = 5$ and $36x = 61$, giving $x = 61/36$. Then $y = 8 - 4(61/36) =$ $8 - 244/36 = 11/9$. Thus $x + y = 61/36 + 11/9 = 61/36 + 44/36 = 105/36 = 35/12.$
**Faster approach:** Use elimination: multiply $4x + y = 8$ by $7$ to get $28x + 7y = 56$, add to $8x - 7y = 5$ to eliminate $y$, yielding $36x = 61$ immediately. This elimination step is a time-saving method for similar two-variable linear systems.'),
  ('00299247-ff6b-5f41-82c3-eef6b90b025a', 0, null, '**Choice A is correct.** In the linear equation $H = 2.419L + 22.83$, the coefficient $2.419$ is the slope, which gives the change in $H$ (estimated height, in inches) for a one-unit increase in $L$ (femur length, in inches). Thus $2.419$ represents the increase in estimated height, in inches, for each additional inch of femur length.
**Choice B is incorrect.** That choice reverses the dependent and independent variables: $2.419$ is change in $H$ per change in $L$, not the change in $L$ per change in $H$.
**Choice C is incorrect.** This misinterprets the slope and uses $22.83$ incorrectly; $2.419$ is per 1-inch change in $L$ , not per a $22.83$-inch change in $H$.
**Choice D is incorrect.** $22.83$ (the intercept) would relate to height when $L = 0$, not $2.419$; $2.419$ is not an estimated height value.
**Faster approach:** Identify the slope and intercept: the number multiplying $L$ is the rate of change (units: inches of height per inch of femur), so pick the choice that describes change in $H$ per 1-inch change in $L$.'),
  ('4891c60d-5be7-5482-ae06-1baf82b59fb1', null, array['175']::text[], '**The correct answer is 175.** Substitute $x = 75$ into the given equation: $0.10(75) + 0.20y = 0.17(75 + y)$. This gives $7.5 + 0.20y = 12.75 + 0.17y$. Subtract $0.17y$ from both sides and subtract $7.5$ from both sides to get $0.03y = 5.25$. Divide both sides by $0.03$ to find $y = \frac{5.25}{0.03} = 175$.
**Faster approach:** Use the alligation (mixture) method. The target concentration $17%$ is $7$ percentage points above $10%$ and $3$ points below $20%$, so the ratio of $20%$ solution to $10%$ solution is $7 : 3$. With $75$ gallons of the $10%$ solution, $y = \frac{7}{3} \cdot 75 = 175$ gallons.'),
  ('b4f6da83-07f4-584e-9aeb-31318e63b572', null, array['552']::text[], '**The correct answer is 552.** First translate percentages to decimals. Since $0.09% = 0.0009$, the equation $0.0009b = 0.1242$ gives $b = 0.1242/0.0009$. Compute $b = (0.1242 \times 1000)/(0.9) = 124.2/0.9 = 138$. Next use the relation that $b$ is $25%$ of $c$, so $b = 0.25c$, hence $c = b/0.25 = 4b = 4 \times 138 = 552$.
**Faster approach:** Convert percentages to multipliers and work from right to left: divide by $0.0009$ to get $b$, then multiply by $4$ (reciprocal of $0.25$) to get $c$. This uses two straightforward arithmetic steps without rearranging symbolic expressions.'),
  ('5f639167-7cc1-57ab-9849-6eeb3569fa22', 1, null, '**Choice B is correct.** The given line has equation $y = 3x + 20$, so its slope is $3$. A line perpendicular to it has slope $-\frac{1}{3}$. Since line $h$ passes through $(0,0)$, its equation is $y = -\frac{1}{3}x$. Substituting $x = 18$ gives $t = y =$ $-\frac{1}{3}(18) = -6$.
**Choice A is incorrect.** $-54$ would come from using slope $-3$ instead of the perpendicular slope $-\frac{1}{3}$ (or from multiplying rather than dividing by 3).
**Choice C is incorrect.** $6$ has the wrong sign; it would be $+\frac{1}{3}(18)$, which is not perpendicular to the original line.
**Choice D is incorrect.** $54$ is far from the line $y = -\frac{1}{3}x$ and results from an arithmetic error such as using slope $3$ and multiplying 18 by 3.
**Faster approach:** Convert $-3x + y = 20$ to slope form to get slope $3$, take the negative reciprocal $-\frac{1}{3}$ for the perpendicular line through the origin, and compute $y = -\frac{1}{3}(18) = -6$.'),
  ('491a15a6-4611-5ea7-a3b7-a7a5a22bf4d1', 3, null, '**Choice D is correct.** Multiply the first equation by $-2$: $-2(-3x + 9y) = -2(2)$ gives $6x - 18y = -4$, but the second equation is $6x - 18y = 4$. The left sides are identical while the right sides are different, so the two equations represent parallel lines with no intersection, hence no solution.
**Choice A is incorrect.** Multiplying the first equation by $-1$ gives $3x - 9y = 2$, which is exactly the second equation, so the system has infinitely many solutions, not none.
**Choice B is incorrect.** The two equations are not scalar multiples of each other, so they represent distinct nonparallel lines that intersect in exactly one solution.
**Choice C is incorrect.** Multiplying the first equation by $-3$ gives $-9x + 27y = -6$, which matches the second equation, so the system has infinitely many solutions.
**Faster approach:** Check whether one equation is a constant multiple of the other. If coefficients are proportional but constants are not, the system has no solution; if both coefficients and constant are proportional, it has infinitely many solutions; otherwise it has a single solution.'),
  ('a0690650-254e-5af2-a183-b69481aff2ab', 2, null, '**Choice C is correct.** The exponent is $2x$ where $x$ is in years, so increasing $x$ by $0.5$ (6 months) increases the exponent by $2(0.5) = 1$, which multiplies the balance by $1.003$, i.e., an increase of $0.3%$ over that 6-month interval.
**Choice A is incorrect.** It gives a dollar amount increase of about \$3, but $1.003$ is a multiplicative factor (a $0.3%$ increase), not an additive \$3 increase; the actual dollar change depends on the current balance.
**Choice B is incorrect.** A 2-year increase corresponds to multiplying by $(1.003)^{4}$, not by $1.003$, so the statement about \$3 after 2 years is wrong.
**Choice D is incorrect.** The factor $1.003$ applies every half-year, not every 2 years; over 2 years the factor is $(1.003)^{4}$, not $1.003$.
**Faster approach:** Note that $2x$ means each $0.5$-year step increases the exponent by 1, so the base $1.003$ is the growth factor for each 6-month interval — immediately yields choice C.'),
  ('13b6ece4-5c46-5dce-b419-204777b68435', 0, null, '**Choice A is correct.** To determine whether $x + 9r$ is a factor of the expression $2x^{2} + (18r + 5)x + 45r$, we can use polynomial division or the factor theorem. According to the factor theorem, if $x + 9r$ is a factor, then substituting $x = -9r$ into the expression should yield zero.
Substituting $x = -9r$ gives:
$2(-9r)^{2} + (18r + 5)(-9r) + 45r = 2(81r^{2}) - (162r^{2} + 45r) + 45r = 162r^{2} - 162r^{2} = 0.$
This confirms that $x + 9r$ is indeed a factor.
Now let’s check option II, $2x + 5$. Again, using the factor theorem, if $2x + 5$ is a factor, substituting $x = -\frac{5}{2}$ should yield zero.
Substituting $x = -\frac{5}{2}$ gives:
$2(-\frac{5}{2})^{2} + (18r + 5)(-\frac{5}{2}) + 45r = 2(\frac{25}{4}) - \frac{5(18r+5)}{2} + 45r.$
Calculating this does not yield zero for all $r$, so $2x + 5$ is not a factor.
Thus, option I is correct, and option II is incorrect.
**Choice B** is incorrect because $2x + 5$ does not satisfy the factor condition as shown above.
**Choice C** is incorrect since it includes the incorrect factor $2x + 5$.
**Choice D** is also incorrect because it implies that both factors are not valid, while $x + 9r$ is indeed a valid factor.'),
  ('a1fa56ee-c785-52b5-b5da-2d75f8e617fe', 2, null, '**Choice C is correct.** Divide both sides by 5 to get $∣x - 8∣ = \frac{k}{5}$. An equation $∣x - 8∣ = c$ has exactly one real solution only when $c = 0$, because then $x - 8 = 0$ gives the single solution $x = 8$. Thus $\frac{k}{5} = 0$ is the required value.
**Choice A is incorrect.** If $\frac{k}{5} = 8$ (or $-8$) then $∣x - 8∣ = 8$ would give two solutions $x = 0$ and $x = 16$ (and $\frac{k}{5} =$ $-8$ is impossible because absolute value equals a negative number has no solution).
**Choice B is incorrect.** $\frac{k}{5} = -8$ gives no solutions because an absolute value cannot equal a negative number, so it cannot produce exactly one solution.
**Choice D is incorrect.** $\frac{k}{5} = 8$ produces two distinct solutions, not one.
**Faster approach:** Recognize $∣x - 8∣ = c$ yields two solutions if $c > 0$, one if $c = 0$, none if $c < 0$; therefore choose $c = 0$ immediately.'),
  ('27a17fc4-c57c-544f-9726-283cecc5b6b7', 0, null, '**Choice A is correct.** Solve: $8∣7 - x∣ + 2 = 82 ⇒ 8∣7 - x∣ = 80 ⇒ ∣7 - x∣ = 10$. Then $7 - x = 10 ⇒ x = -3$, or $7 - x = -10 ⇒ x = 17$. The sum of the solutions is $-3 + 17 = 14$, so A is correct.
**Choice B is incorrect.** 10 is not the sum; the two solutions found are $-3$ and $17$, which add to $14$, not $10$.
**Choice C is incorrect.** $-3$ is one of the solutions, but the question asks for the sum of both solutions; $-3$ alone is not the sum.
**Choice D is incorrect.** $-14$ is the negative of the correct sum; the actual sum is $14$, not $-14$.
**Faster approach:** For any equation $∣a - x∣ = k$, the two solutions are $a \pm k$, whose sum is $2a$. Here $∣7 - x∣ =$ $10$ gives solutions $7 \pm 10$, so the sum is $2 \cdot 7 = 14$. This shortcut works for every absolute-value equation of the form $∣a - x∣ = k$.'),
  ('8c6a1457-7d80-5585-a401-9ab2cd1d4b79', null, array['341']::text[], '**The correct answer is 341.** Because the seal is at the surface at $t = 0$ and $t = 16$, the quadratic can be written as $g(t) = kt(16 - t)$. The vertex occurs at $t = 8$, where $g(8) = 64k = 396.8$, so $k = 396.8/64 = 6.2$. Thus $g(t) = 6.2t(16 - t)$ and $g(11) = 6.2 \cdot 11 \cdot 5 = 341$, so the estimated depth at 11 minutes is 341 meters (to the nearest meter).
**Faster approach:** Use the fact that symmetric roots 0 and 16 place the vertex at 8, so set $g(t) = kt(16 - t)$, solve $64k = 396.8$ for $k$, then evaluate at $t = 11$. This avoids expanding the quadratic.'),
  ('70555fa5-4cb4-5fc8-b64c-1949cd19c09f', 3, null, '**Choice D is correct.** Place X at the origin, Z at (a,0), and Y at (0,b). With h = √(a^2+b^2), the point V is 501 units from Z along YZ, so V = (a(1-501/h), 501b/h). The vector WV is perpendicular to YZ, so the horizontal component of WV is $Δx = \frac{by_{V}}{a} = \frac{501b^{2}}{ah}$. Then $WV^{2} = (Δx)^{2} + y_{V}^{2} = (501^{2}b^{2}/a^{2})$, so $WV = 501 \cdot (b/a)$. Given $WV = 668$, $b/a = 668/501 = 4/3$, and $\tan Z = b/a = 4/3$.
**Choice A is incorrect.** It gives $\tan Z = 3/5$, but using the relation $WV = 501 \cdot \tan Z$ would yield $WV = 501 \cdot$ $3/5 = 300.6 \ne 668$.
**Choice B is incorrect.** $\tan Z = 3/4$ would give $WV = 501 \cdot 3/4 = 375.75$, not the given 668.
**Choice C is incorrect.** $\tan Z = 4/5$ would give $WV = 501 \cdot 4/5 = 400.8$, which is inconsistent with $WV =$ $668$.
**Faster approach:** Use coordinates or similar-right-triangle reasoning to get the general relation $WV = ZV \cdot$ $\tan Z$. Then compute $\tan Z = WV /ZV = 668/501 = 4/3$ directly.'),
  ('b7406481-235c-558f-8fc1-56b5a47fccf1', 3, null, '**Choice D is correct.** Let the initial mass of each chemical be $m$. A $2,600%$ increase means chemical A becomes $m(1 + 26) = 27m$. A $380%$ increase means chemical B becomes $m(1 + 3.8) = 4.8m$. The ratio A to B at the end is $\frac{27m}{4.8m} = \frac{27}{4.8} = \frac{270}{48} = \frac{45}{8} = 5.625 \approx 5.63$, so Choice D is correct.
**Choice A is incorrect.** Choice A ($29.80$) is far too large; it would result from an incorrect multiplier for A (for example, using $29m$ instead of $27m$) or an incorrect, much smaller multiplier for B. It does not follow from the correct percent-to-multiplier conversion.
**Choice B is incorrect.** Choice B ($22.20$) comes from an arithmetic mistake when dividing the correct multipliers $27$ and $4.8$ (for example, miscomputing the quotient). It does not equal $27/4.8$, so it is wrong.
**Choice C is incorrect.** Choice C ($6.84$) corresponds to forgetting to add 1 when converting percent increases to multipliers: using $26/3.8 = 6.84$ (i.e., using $2600%$ as $26$ and $380%$ as $3.8$ without the +1). That misinterpretation yields the wrong ratio.
**Faster approach:** Convert each percent increase to a multiplier (final = initial × (1 + percent/100)), then divide the two multipliers. This always works for questions asking how many times one quantity is of another after percent increases.'),
  ('2fe5583e-5c33-59b5-af84-e91dd584db3c', null, array['10']::text[], '**The correct answer is 10.** Rearrange the equation to standard quadratic form: $r^{2} - (q + 8)r + 87 = 0$. For this quadratic to have no real solutions, its discriminant must be negative: $D = (q + 8)^{2} - 4(1)(87) = (q +$ $8)^{2} - 348 < 0$. Thus $(q + 8)^{2} < 348$. Since $18^{2} = 324 < 348$ and $19^{2} = 361 > 348$, the integer values of $q + 8$ that satisfy the inequality are $-18,-17,…,17,18$. The largest of those is $18$, so $q = 18 - 8 = 10$, which indeed gives $D = 324 - 348 = -24 < 0$.
**Faster approach:** Put the quadratic in standard form and use the discriminant test $b^{2} - 4ac < 0$; then take square roots to get an interval for $b$ and pick the largest integer that fits. This avoids solving for roots explicitly and works for any similar problem.'),
  ('b96d65e2-18a1-58bd-8685-7b93367e5f12', 1, null, '**Choice B is correct.** Let the leg length be $x$. In an isosceles right triangle the hypotenuse is $x\sqrt{2}$, so the perimeter is $2x + x\sqrt{2} = x(2 +$$\sqrt{2})$. Set this equal to the given perimeter: $x(2 +$$\sqrt{2}) = 34 + 34\sqrt{2} = 34(1 +$ $\sqrt{2})$. Thus $34\frac{1 + \sqrt{2}}{\sqrt{2}}$. Multiply numerator and denominator by the conjugate $(2 -$$\sqrt{2})$: $x =$ $34\frac{(1 + \sqrt{2}x)(=2 - \sqrt{2}2 +)}{4 - 2} = 34\frac{\sqrt{2}}{2} = 17\sqrt{2}$.
**Choice A is incorrect.** A leg of $17$ would make the perimeter $2(17) + 17\sqrt{2} = 34 + 17\sqrt{2}$, which is less than the given perimeter because the $\sqrt{2}$ term is only $17\sqrt{2}$ not $34\sqrt{2}$.
**Choice C is incorrect.** A leg of $34$ gives perimeter $68 + 34\sqrt{2}$, which has too large an integer part (68 instead of 34) and does not match the given total.
**Choice D is incorrect.** A leg of $34\sqrt{2}$ yields perimeter $68\sqrt{2} + 34 \cdot 2 = 68 + 68\sqrt{2}$, far larger than the given value.
**Faster approach:** Write perimeter as $x(2 +$$\sqrt{2}) = 34(1 +$$\sqrt{2})$, then divide: $x = 34\frac{1+\sqrt{2}}{2+\sqrt{2}}$. Multiply by the conjugate $(2 -$$\sqrt{2})$ once to simplify immediately to $17\sqrt{2}$.')
